ARTICLES=[]
def add(cat,slug,title,intro,blocks,tip,image=None,sources=(),place=None,group=None,status=None):
    ARTICLES.append(dict(category=cat,slug=slug,title=title,intro=intro,sections=[dict(title=t,text=p) for t,p in blocks],tip=tip,image=image or dict((c[0],c[3]) for c in CATEGORIES)[cat],sources=list(sources),place=place,group=group or 'Explorar',status=status))



add('guia','seguridad-y-emergencias','Seguridad y emergencias en Punta Arenas','Una guía para preparar contactos y actuar con calma ante problemas de salud, documentos, clima o excursiones, sin sustituir la información oficial.',[
('01 · Números de emergencia en Chile','En Chile los teléfonos nacionales son 131 para ambulancias SAMU, 132 para Bomberos y 133 para Carabineros. Para solicitar ayuda explica la ubicación más precisa que puedas, el tipo de incidente, cuántas personas necesitan atención y un teléfono de contacto. No uses estos números para consultas turísticas ordinarias.'),
('02 · Atención de salud y seguros','Antes de viajar guarda la póliza y el teléfono de asistencia de tu seguro. Comprueba qué centros de atención y costos cubre, cómo solicitar autorización y cómo tramitar reembolsos. En una emergencia prioriza la atención inmediata; los trámites del seguro se pueden organizar después.'),
('03 · Viento, nieve y cortes de ruta','Consulta avisos de la Dirección Meteorológica de Chile y recomendaciones de las autoridades regionales. Los viajes interurbanos pueden verse alterados por hielo o condiciones del camino. Evita rutas largas cuando exista una advertencia de seguridad; comprueba información reciente con el transportista y no confíes solo en el tiempo estimado de un mapa.'),
('04 · Senderismo y lugares remotos','Avisa a una persona de confianza qué sendero harás y cuándo esperas regresar. Comprueba accesos, dificultad, horarios de luz, estado del terreno y cobertura de telefonía. Lleva agua, abrigo, batería y orientación adecuada; los grupos sin experiencia deben valorar contratar guías habilitados.'),
('05 · Navegaciones y cambios de itinerario','Si el operador suspende una excursión por clima o seguridad, solicita por escrito la alternativa de reprogramación o devolución según la reserva. La protección de la fauna y las restricciones marítimas también importan. Nunca presiones a un operador para navegar bajo condiciones inseguras.'),
('06 · Pérdida de documentos','Anota los datos de tu consulado y conserva copias seguras de pasaporte, reservas y póliza. Ante pérdida o robo solicita orientación de la autoridad competente y del consulado, según corresponda. No asumas que una fotografía del documento es suficiente para embarcar o cruzar fronteras.'),
('07 · Si te roban o extravías objetos','Protege primero tus tarjetas y cuentas, intenta localizar el último lugar visitado y consulta con alojamiento y transportista. Para denuncias utiliza los canales de la autoridad competente. No difundas públicamente datos sensibles o números completos de tus documentos.'),
('08 · Viajar con niños, mayores o movilidad reducida','Confirma con anticipación accesibilidad, duración de recorridos, baños y condiciones de traslado. Prioriza actividades con opciones de descanso y deja un contacto de emergencia disponible. Una excursión anunciada como fácil puede incluir pasarelas, escalones o superficies resbaladizas.'),
('09 · Preparar una ficha de emergencia','Guarda nombre del alojamiento, dirección, contacto de una persona de confianza, datos de seguro y medicamentos esenciales. Lleva la información de forma accesible sin exhibir detalles privados. Si vas a áreas sin señal acuerda de antemano una hora de control.'),
('10 · Fuentes que conviene revisar','Verifica en organismos oficiales la información sanitaria, avisos meteorológicos y las condiciones de parques. Los teléfonos y procedimientos específicos de hospitales, farmacias y oficinas pueden cambiar: no los inventamos y siempre deben comprobarse antes de publicarlos.')
],'Ante un cambio de clima o una excursión cancelada, la mejor decisión a veces es quedarse en la ciudad y disfrutar algo bajo techo. La seguridad vale más que una foto.','ciudad',('salud','sernatur','chile'),'Punta Arenas, Magallanes, Chile','Salud y tranquilidad')

add('guia','presupuesto','Cuánto cuesta viajar a Punta Arenas','Organiza tu presupuesto de viaje con categorías reales, sin precios inventados ni promesas de que todas las temporadas cuestan lo mismo.',[
('01 · Separa gastos fijos y variables','Haz una lista por persona de alojamiento, alimentación, movilidad urbana y excursiones. Agrega tasas de acceso cuando correspondan y gastos de comunicación, seguro y equipaje. Mantén una reserva para cambios de clima y traslados imprevistos.'),
('02 · Alojamiento: más allá de la tarifa por noche','Compara habitaciones, hostales y departamentos con las mismas condiciones: ubicación, calefacción, impuestos aplicables, política de cancelación, horario de entrada y traslados. Un alojamiento más barato fuera del centro puede resultar más caro cuando sumas taxis.'),
('03 · Cuánto reservar para comer','Planea desayuno, almuerzo, cena y alguna pausa. Combinar supermercados, cafeterías y restaurantes ayuda a controlar el gasto. Los mariscos y especialidades regionales pueden tener valores diferentes de un menú cotidiano; consulta precios publicados por el local antes de pedir.'),
('04 · Movilidad y excursiones','Distingue recorridos caminables de viajes que exigen vehículo, barcaza, navegación o guía. Una salida desde Punta Arenas no siempre incluye recogida en el hotel, entradas o alimentación. Pide cotizaciones por escrito e identifica lo incluido para comparar correctamente.'),
('05 · Presupuesto por estilo de viaje','Viajero económico: hostal o habitación compartida, comidas sencillas y selección limitada de excursiones. Viajero intermedio: alojamiento céntrico y varias actividades organizadas. Viaje cómodo: servicios privados y mayor flexibilidad. Calcula el total según fechas reales; no presentamos un monto fijo sin datos verificados.'),
('06 · Temporada alta y reservas','En fechas de mayor demanda puede reducirse la oferta disponible, especialmente para alojamientos y actividades con cupo. Reservar con anticipación ayuda a escoger, pero revisa condiciones de modificación y devolución ante cancelaciones meteorológicas.'),
('07 · Efectivo, tarjetas y conversión','Los gastos se expresan en pesos chilenos. Revisa comisiones internacionales y conversión de tu banco, conserva una tarjeta de respaldo y algo de efectivo para imprevistos. Antes de cambiar dinero consulta tipo de cambio y condiciones vigentes.'),
('08 · Un presupuesto de tres días','Suma tres noches de alojamiento si tu vuelo y salida lo requieren, tres días de alimentación y traslados de llegada y salida. Añade una actividad terrestre y una marítima solo si realmente se ajustan a la temporada. Reserva margen para una reprogramación; evita programar el último día sin holgura.'),
('09 · Gastos que se olvidan','Incluye propinas voluntarias, lavandería, artículos de invierno, datos móviles, recuerdos, posibles taxis nocturnos y seguros de actividad. Para viajar a Argentina comprueba aparte documentación, transporte, cambio de moneda y gastos fronterizos.'),
('10 · Cómo actualizar el presupuesto','Revisa el costo total por viajero antes de confirmar y guarda fecha de cotización. Nunca utilices un precio sin identificar proveedor, servicio incluido y moneda. Esta guía ofrece el método de cálculo, no tarifas garantizadas.')
],'El precio más bajo no siempre significa el viaje más barato. Comparo el costo total, las distancias y la posibilidad de cambiar una reserva cuando el tiempo decide otra cosa.','ciudad',('chile','sernatur'),'Punta Arenas, Magallanes, Chile','Planifica tu viaje')

add('guia','informacion-practica','Información práctica antes de viajar a Punta Arenas','Electricidad, conexiones, horarios, compras y pequeños detalles que hacen más fácil tu llegada a la Patagonia austral.',[
('01 · Moneda y pagos','En Chile se utiliza el peso chileno (CLP). En áreas urbanas suelen aceptarse tarjetas, pero lleva una opción alternativa. Consulta antes de viajar las comisiones, límites y compatibilidad de tus medios de pago.'),
('02 · Enchufes y electricidad','En Chile la red eléctrica doméstica es de 220 V y 50 Hz; se utilizan habitualmente enchufes de tipos C y L. Comprueba el voltaje admitido en tus cargadores antes de conectarlos y utiliza adaptadores apropiados; los adaptadores de clavija no siempre convierten voltaje.'),
('03 · Internet y comunicación','Revisa si tu teléfono acepta eSIM y qué roaming tiene tu operador. La señal puede disminuir fuera de las áreas pobladas: descarga mapas, documentos de reserva y números importantes para consulta sin conexión.'),
('04 · Horarios y feriados','Los horarios de comercios, museos, bancos y actividades dependen del establecimiento y del día. En feriados y temporada invernal comprueba aperturas antes de salir. No generalices el horario de un local a toda la ciudad.'),
('05 · Agua, alimentación y abrigo','En la ciudad, utiliza agua de redes habilitadas y atiende cualquier aviso puntual del prestador local. Lleva abrigo por capas y ropa cortaviento incluso si el itinerario parece urbano. Si tienes necesidades alimentarias especiales, contacta a los locales con anticipación.'),
('06 · Traslado desde el aeropuerto','Averigua con tiempo los transportes disponibles para tu horario de llegada, especialmente en vuelos nocturnos. Confirma condiciones de equipaje y tarifa total. Si la recepción del alojamiento cierra temprano, coordina la entrada antes del viaje.'),
('07 · Aplicaciones y mapas','Guarda mapas sin conexión, rutas de bus cuando existan publicadas, horarios del operador turístico y tu póliza. Lleva el itinerario accesible también fuera del móvil, por ejemplo en un archivo descargado.'),
('08 · Navegaciones y parques','Revisa temporada, reservas y condiciones actualizadas antes de recorrer grandes distancias. Que un parque aparezca abierto en una publicación antigua no garantiza acceso ese mismo día; condiciones del mar y camino cambian.'),
('09 · Cruces fronterizos','Si piensas continuar hacia Argentina, comprueba documentación migratoria, declaración aduanera, permisos del vehículo de alquiler y horarios fronterizos en fuentes oficiales. No supongas que todos los cruces ofrecen el mismo servicio.'),
('10 · Antes de salir del alojamiento','Carga el teléfono, revisa pronóstico y estado de la actividad, guarda dirección del alojamiento, lleva agua y confirma la hora de regreso. Deja margen suficiente antes de vuelos, conexiones en bus o embarques.')
],'Un buen viaje empieza con cinco minutos de preparación cada mañana. Elige una ruta posible para el tiempo que tienes y deja una alternativa agradable para cuando cambie el viento.','ciudad',('chile','puq','sernatur'),'Punta Arenas, Magallanes, Chile','Planifica tu viaje')


add('guia','puerta-patagonia','Punta Arenas: puerta de entrada a la Patagonia','Desde la capital de Magallanes puedes organizar diferentes rutas por la Patagonia chilena y argentina. Esta guía distingue destinos, conexiones y excursiones para que no confundas distancias ni tiempos.',[
('Comienza por conocer Punta Arenas','Dedica al menos una jornada a la Plaza Muñoz Gamero, el borde costero, el patrimonio y la gastronomía de Punta Arenas. La ciudad merece ser parte del viaje, no solo un punto de conexión hacia parques más lejanos.'),
('Puerto Natales: otra ciudad y otra base','Puerto Natales es un destino diferente, con su propia oferta de alojamientos, operadores y conexiones hacia el Parque Nacional Torres del Paine. El traslado terrestre ocupa varias horas según condiciones de ruta, paradas y operador; no lo organices como si fuera un barrio de Punta Arenas.'),
('Torres del Paine: planifica más que una foto','El parque tiene sectores y senderos de exigencias muy distintas. Infórmate de entradas, accesos, transporte y condiciones de la ruta concreta que quieras realizar. Una visita panorámica no equivale a un trekking prolongado; para circuitos extensos necesitas más jornadas y reservas específicas.'),
('Tierra del Fuego y Porvenir','El acceso desde el continente depende de las rutas y cruces marítimos que elijas. Consulta salidas de TABSA, tiempos de espera y transporte terrestre de regreso. La Reserva Natural Pingüino Rey no está junto al puerto: requiere traslado adicional y condiciones de visita verificadas.'),
('Isla Magdalena y navegación','La observación de pingüinos magallánicos requiere una excursión marítima estacional que puede modificarse por seguridad y condiciones del mar. Verifica con el operador si incluye desembarco, interpretación, duración y traslados. Nunca des por garantizada la presencia de fauna.'),
('Fuerte Bulnes y Parque del Estrecho','Es una excursión terrestre de patrimonio que se puede organizar desde Punta Arenas sin cruzar hacia Puerto Natales. Comprueba horario, entrada, condiciones del camino y duración total antes de decidir si ir en vehículo propio o tour.'),
('Cruzar hacia la Patagonia argentina','Si tu itinerario incluye El Calafate, Río Gallegos o Ushuaia, revisa conexiones reales, fronteras, documentos, aduanas y permisos para el vehículo. Un mapa que muestre cercanía geográfica no reemplaza consultar los cruces y horarios vigentes.'),
('Cómo armar una ruta realista','Para una estancia breve prioriza Punta Arenas y una excursión cercana. Para combinarla con Puerto Natales asigna días de traslado y una base distinta. Si deseas Tierra del Fuego o Argentina, añade margen logístico; evita comprar conexiones ajustadas después de navegaciones.'),
('Viajar sin automóvil','Puedes combinar bus interurbano, excursiones organizadas y traslados contratados. Verifica cada tramo por separado: no todos los servicios incluyen búsqueda en hotel ni conectan directamente con aeropuertos o terminales. Guarda siempre el plan de regreso.'),
('Mi consejo para explorar el sur','Elige dos o tres experiencias principales y organízalas alrededor de los días disponibles. Deja una jornada flexible si incluyes navegación y ten un plan cultural alternativo. La Patagonia se disfruta mejor cuando el itinerario respeta la geografía y el clima.')
],'Punta Arenas, Puerto Natales y Tierra del Fuego ofrecen viajes distintos. En lugar de intentar conocerlo todo en un día, elige un recorrido que puedas disfrutar de verdad.','ciudad',('chile','natales','barcaza','estrecho','sernatur'),'Punta Arenas, Región de Magallanes, Chile','Conexiones patagónicas')

add('guia','conducir-patagonia','Arrendar un vehículo y conducir por Patagonia','Conducir por Magallanes abre posibilidades, pero exige organizar combustible, distancias, viento, estado de las rutas y permisos fronterizos antes de salir.',[
('Elegir si realmente necesitas un auto','Para el centro de Punta Arenas puede resultar más práctico caminar o usar transporte urbano. El vehículo adquiere utilidad para recorridos por sectores apartados, siempre que el camino y tu experiencia lo permitan. Compara alquiler, combustible, seguro, estacionamientos y excursiones con traslado incluido.'),
('Antes de reservar','Comprueba edad mínima, antigüedad de licencia, requisitos de tarjeta, depósito o garantía y qué coberturas incluye el contrato. Pregunta por franquicias, daños en parabrisas, neumáticos y circulación por caminos no pavimentados. Conserva las condiciones por escrito.'),
('Documentos y conductores','Lleva licencia válida para conducir en Chile conforme a tu país de origen y situación migratoria, documentación del vehículo y contrato de alquiler. Confirma con la compañía si aceptan tu licencia o requieren documentación adicional. Solo deben conducir las personas autorizadas en el contrato.'),
('Viento y conducción segura','En tramos abiertos pueden existir ráfagas transversales intensas. Reduce velocidad de acuerdo con las condiciones y evita maniobras bruscas, sobre todo al adelantar vehículos grandes. Si hay alerta o cierre de camino, modifica la ruta. No intentes conducir largas distancias cansado después de un vuelo.'),
('Ripio, hielo y caminos apartados','Pregunta al arrendador si la ruta prevista está permitida. Revisa neumáticos, equipamiento y estado vial antes de salir. El ripio puede reducir la adherencia y proyectar piedras; el hielo exige aún mayor precaución. No te adentres en caminos aislados solo porque aparecen en el mapa.'),
('Combustible y señal de teléfono','Antes de viajar a sectores remotos, comprueba dónde hay estaciones de servicio operativas y la autonomía del vehículo. Guarda mapas fuera de línea, agua, abrigo y datos de asistencia en ruta. Una ruta con señal deficiente merece un margen mayor de seguridad.'),
('Estacionamientos y ciudad','Verifica señalización de estacionamiento, restricciones y eventuales cobros. En lugares turísticos respeta accesos, áreas protegidas y propiedades privadas. No dejes objetos de valor visibles dentro del vehículo.'),
('Ferry y Tierra del Fuego','Consulta rutas, reservas y condiciones de transporte de vehículos de TABSA. Calcula anticipadamente embarque, espera y recorrido posterior al desembarcar; un ferry no siempre garantiza conexión inmediata con tu siguiente actividad.'),
('Cruce hacia Argentina','No supongas que un auto arrendado en Chile puede salir libremente del país. Pregunta expresamente por autorización del arrendador, seguros internacionales y documentos exigidos en frontera. Comprueba requisitos migratorios y aduaneros antes de reservar alojamientos al otro lado.'),
('Revisión del vehículo y devolución','Fotografía el estado del vehículo al retirarlo y registra el combustible. Aclara asistencia ante averías, teléfonos del proveedor y cargos por devolución tardía o en otra ciudad. Para llegar a un vuelo, deja margen suficiente por clima y tránsito.')
],'Un auto da libertad, pero no elimina las distancias ni cambia el tiempo. En Patagonia, la mejor ruta es la que puedes recorrer con seguridad y con margen para volver.','ciudad',('chile','barcaza','angostura','sernatur'),'Punta Arenas, Chile','Llegar y moverse')


add('guia','mejor-epoca','Mejor época para viajar a Punta Arenas','La mejor fecha depende de lo que deseas vivir: pingüinos, patrimonio, senderismo, celebraciones o días tranquilos. Esta guía te ayuda a elegir por experiencia y no por una sola fotografía.',[
('01 · Verano austral: diciembre a febrero','Hay jornadas largas que permiten organizar recorridos por la ciudad y excursiones. Eso no elimina el viento ni asegura un mar tranquilo. En fechas de alta demanda conviene reservar alojamiento, excursiones y transporte con anticipación.'),
('02 · Otoño: marzo a mayo','La luz disminuye gradualmente y las temperaturas empiezan a bajar. Es una etapa interesante para museos, gastronomía y paseos fotográficos urbanos, combinando siempre un plan interior por si el clima cambia. Consulta qué excursiones siguen funcionando.'),
('03 · Invierno: junio a agosto','Los días tienen menos horas de luz y puede haber hielo o nieve. Es una oportunidad para experimentar otra cara de Magallanes, pero requiere ropa adecuada, recorridos realistas y revisar caminos. No presupongas que las navegaciones de verano operan igual en invierno.'),
('04 · Primavera: septiembre a noviembre','Aumentan las horas de luz y comienzan a cobrar protagonismo las actividades al aire libre. Algunas visitas de fauna tienen ventanas estacionales específicas; verifica aperturas y condiciones con el operador, en lugar de suponer una fecha fija de llegada de animales.'),
('05 · ¿Cuándo ver pingüinos?','Las excursiones a Isla Magdalena y otros lugares de observación se vinculan a temporadas y condiciones operativas. Consulta fechas vigentes con el operador y las autoridades del área protegida. La observación de fauna libre nunca se garantiza al cien por ciento.'),
('06 · ¿Cuándo conviene hacer senderismo?','Elige la estación según las horas de luz, el estado de senderos y tu experiencia. Algunos itinerarios son accesibles en determinadas temporadas y otros requieren guías o preparación especial. No confundas la visita urbana a Punta Arenas con un trekking en Torres del Paine.'),
('07 · Viaje gastronómico y cultural','Museos, patrimonio, cafeterías y cocina regional pueden disfrutarse durante gran parte del año, sujetos a horarios. En temporada fría son especialmente útiles para armar jornadas sin depender por completo de caminatas largas.'),
('08 · Eventos y fechas especiales','Revisa el calendario actualizado de eventos municipales, festividades e Invernadas. La fecha de una edición anterior no confirma automáticamente el programa de la próxima. Para festivales populares reserva alojamiento con margen.'),
('09 · Precio y disponibilidad','La demanda varía por temporada y eventos. Cotiza vuelos, hospedaje y tours para fechas concretas; compara precios totales y políticas de cambio. Una temporada de menor demanda puede tener menos alternativas de excursión.'),
('10 · Mi consejo para elegir','Define primero la experiencia imprescindible. Si son pingüinos, confirma su temporada; si es senderismo, investiga la ruta; si quieres conocer la ciudad sin prisas, prioriza las actividades urbanas y deja días flexibles. Después compra el pasaje.')
],'No existe un mes perfecto para todo. La mejor época es aquella en que puedes disfrutar lo que realmente quieres conocer y tienes un plan alternativo para el viento.','ciudad',('chile','sernatur','invernadas'),'Punta Arenas, Magallanes, Chile','Cuándo venir')

add('guia','costumbres-magallanicas','Costumbres y vida cotidiana magallánica','Conocer Punta Arenas también es entender su forma de vivir: las tradiciones, los sabores del extremo sur y una relación cotidiana con el clima, el estrecho y las distancias.',[
('01 · Una identidad marcada por el estrecho','Punta Arenas se desarrolló como puerto y lugar de encuentro de rutas marítimas. Su arquitectura y museos cuentan historias de comercio, migraciones y trabajo. Un recorrido patrimonial ayuda a mirar la ciudad más allá de sus atractivos naturales.'),
('02 · Pueblos originarios y memoria','La historia regional incluye a pueblos originarios como los kawésqar, yagán, selk’nam y aonikenk. Sus historias son distintas y merecen tratamiento respetuoso: visita espacios culturales y evita reducir sus identidades a un recuerdo decorativo.'),
('03 · El viento forma parte de la rutina','La gente adapta vestimenta, caminatas y planes a las condiciones australes. Lleva una prenda cortaviento incluso para un trayecto corto y no sorprendas a nadie programando una navegación como actividad infalible.'),
('04 · Gastronomía de la región','Entre las especialidades reconocidas están el cordero magallánico y la centolla, además de preparaciones caseras y productos marinos. Elige locales concretos, verifica horarios y precios, y pregunta por disponibilidad estacional de los platos.'),
('05 · La sobremesa y los espacios de encuentro','Cafeterías, restaurantes y encuentros familiares ofrecen una forma tranquila de acercarse al ritmo de la ciudad. No trates todos los barrios como zonas turísticas idénticas; cada sector tiene sus propios servicios y horarios.'),
('06 · Invernadas y celebraciones','Las Invernadas y el Carnaval de Invierno son expresiones conocidas de la vida cultural puntarenense. Revisa el programa oficial de cada edición; pueden cambiar recorridos, fechas y medidas de tránsito.'),
('07 · Patrimonio y respeto por la ciudad','Observa edificios históricos, plazas, cementerio y museos respetando horarios y reglas de visita. Pide permiso antes de fotografiar a personas, especialmente a niños, y cuida los espacios culturales y de memoria.'),
('08 · Lenguaje y trato cotidiano','En Punta Arenas se habla español chileno, con expresiones y referencias locales. Una pregunta amable suele ser la mejor forma de aprender. Evita imitar acentos o presentar estereotipos como si fueran la experiencia de toda la población.'),
('09 · Viajar de forma responsable','No dejes residuos en senderos o playas, mantén distancia de la fauna y utiliza recorridos autorizados. En excursiones respeta indicaciones del guía y comunidades locales. Comprar a productores y comercios regionales puede enriquecer la visita.'),
('10 · Una tarde para comprender Magallanes','Combina una plaza histórica con un museo y un almuerzo típico, dejando tiempo para escuchar historias de la ciudad. La vida magallánica no se resume en un tour: se percibe también en la calma de una cafetería y en la forma de recibir el invierno.')
],'Mi consejo es escuchar tanto como fotografiar. Preguntar por un plato tradicional o por la historia de un edificio puede abrir una conversación que recordarás más que un itinerario apurado.','ciudad',('museo-regional','invernadas','chile'),'Punta Arenas, Magallanes, Chile','Cultura magallánica')

add('guia','primera-visita','Punta Arenas por primera vez','Si es tu primera visita al extremo sur de Chile, esta guía te ayuda a organizar la llegada, elegir una base cómoda y disfrutar de la ciudad sin convertir el viaje en una carrera.',[
('01 · Cómo es Punta Arenas','Punta Arenas mira al Estrecho de Magallanes y combina patrimonio, vida urbana y excursiones australes. No es solamente un aeropuerto de paso hacia Torres del Paine: vale la pena dedicarle tiempo al centro histórico, al borde costero, a la memoria de sus habitantes y a sus museos. Sus atractivos están repartidos entre calles caminables y sitios naturales que requieren transporte y planificación.'),
('02 · ¿Cuántos días conviene quedarse?','Con un día completo puedes conocer el centro, la Plaza Muñoz Gamero, parte de la costanera y un museo, según horarios de apertura. Con dos o tres días puedes añadir Fuerte Bulnes o Parque del Estrecho y una salida de naturaleza si el clima y el operador lo permiten. Si sueñas con ver pingüinos, organiza la navegación según su temporada y deja margen por posibles cancelaciones. No programes el paseo marítimo más importante pocas horas antes de tu vuelo.'),
('03 · Al llegar al aeropuerto PUQ','El Aeropuerto Presidente Carlos Ibáñez del Campo está fuera del centro urbano. Antes de embarcar verifica cómo llegarás a tu alojamiento: transporte reservado, taxi habilitado o servicio disponible al aterrizar. Confirma precio, forma de pago, equipaje y horario especialmente si llegas de noche. Evita asumir que todas las aplicaciones de movilidad tendrán autos disponibles en cualquier momento.'),
('04 · Elegir dónde alojarse','Si quieres recorrer patrimonio, restaurantes y servicios a pie, el centro puede ser una base práctica. Para una estadía breve prioriza también calefacción, conexión con el aeropuerto, recepción o procedimiento de entrada tardía y políticas ante excursiones que cambien de fecha. Estar frente al estrecho puede ser precioso, pero no reemplaza verificar accesos y distancias reales.'),
('05 · El primer paseo','Una buena introducción es recorrer la Plaza Muñoz Gamero, reconocer edificios patrimoniales y continuar hacia el borde costero si el tiempo acompaña. El Mirador Cerro de la Cruz ayuda a comprender el trazado urbano y la relación con el estrecho. Alterna exteriores con pausas para entrar en calor; no necesitas recorrer todo en una sola jornada.'),
('06 · Viento, temperatura y horas de luz','El tiempo puede variar en pocas horas y el viento fuerte es parte de la experiencia magallánica. Lleva capas, una chaqueta cortaviento impermeable y zapatos con buen agarre. En verano hay largas jornadas de luz pero no significa calor constante; en invierno hay menos horas para los paseos exteriores. Consulta pronósticos y avisos antes de cualquier salida.'),
('07 · Excursiones y reservas','Separa lo urbano de lo que exige navegación o trayectos largos. Isla Magdalena, Fuerte Bulnes, Tierra del Fuego y Puerto Natales no son paseos intercambiables por duración ni logística. Antes de pagar confirma punto de encuentro, temporada, transporte incluido, cancelaciones meteorológicas y si la excursión es apta para tu grupo.'),
('08 · Comer, pagar y mantenerse conectado','Prueba sabores magallánicos en restaurantes con información actualizada. Lleva una tarjeta aceptada internacionalmente y algo de efectivo en pesos chilenos para situaciones puntuales. Si llegas desde otro país, verifica roaming o eSIM y descarga mapas sin conexión para los tramos fuera de la ciudad.'),
('09 · Errores que conviene evitar','No confundas Punta Arenas con Puerto Natales: son ciudades distintas y el traslado ocupa varias horas. No prometas a tus acompañantes ver fauna silvestre en cualquier fecha. No planifiques jornadas rígidas sin alternativas bajo techo. Finalmente, reserva tiempo para la propia Punta Arenas; su historia y paisajes no son solo una escala.'),
('10 · Mi propuesta de tres días','Día uno: plaza, centro, mirador y costanera, con gastronomía local al final. Día dos: patrimonio del Estrecho y Fuerte Bulnes si las condiciones y el transporte acompañan. Día tres: navegación o experiencia de naturaleza previamente confirmada, reservando un plan alternativo para mal tiempo. Ajusta el orden a horarios reales y nunca lo tomes como un itinerario garantizado.')
],'Si pudiera darte un único consejo para la primera visita, sería dejar espacio para cambiar de planes. En Magallanes la flexibilidad no arruina el viaje: muchas veces lo mejora.','ciudad',('chile','puq','museo','estrecho'), 'Punta Arenas, Magallanes, Chile', 'Comenzar a explorar')

add('guia','mal-tiempo','Qué hacer con viento, lluvia o nieve en Punta Arenas','Un día de viento, lluvia o nieve no tiene por qué ser un día perdido. Aquí tienes ideas reales para adaptar tu recorrido con seguridad y descubrir la ciudad bajo techo.',[
('01 · Primero distingue incomodidad de riesgo','La lluvia ligera puede permitir recorridos cortos con ropa adecuada, pero las rachas fuertes de viento, el hielo y los avisos meteorológicos merecen otra respuesta. Consulta la Dirección Meteorológica de Chile, la información vial y los avisos de las autoridades. Si hay una alerta o recomendación de evitar desplazamientos, cancela las actividades expuestas.'),
('02 · Museo Regional de Magallanes','El Palacio Braun Menéndez es una oportunidad para comprender parte de la historia urbana y social de Punta Arenas. Revisa previamente días de funcionamiento, visitas disponibles y eventuales cierres; no todos los museos funcionan a diario. Es una buena alternativa cuando caminar muchas horas por la costanera resulta incómodo.'),
('03 · Museo Maggiorino Borgatello','Sus colecciones permiten explorar historia natural y aspectos culturales de la región. Es un complemento distinto al Museo Regional. Antes de salir verifica horario, condiciones de entrada y acceso; reservar un plan alternativo cercano es útil si ese día está cerrado.'),
('04 · Museo del Recuerdo y patrimonio','Los espacios que recuerdan la vida de los pioneros y antiguos oficios ayudan a imaginar otra época de Magallanes. Comprueba si la visita requiere coordinación y qué zonas son interiores o exteriores. No lo consideres automáticamente una actividad cien por ciento bajo techo.'),
('05 · Cafeterías y cocina magallánica','Una pausa para un café, un plato caliente o comida típica también forma parte de conocer Punta Arenas. Elige un local según ubicación, horario confirmado y tu presupuesto; evita recorrer largas distancias bajo mal tiempo solo porque un restaurante aparezca recomendado en internet.'),
('06 · Centro cultural, biblioteca y exposiciones','Consulta la cartelera de la Municipalidad y la Fundación Cultural Punta Arenas: exposiciones, talleres y encuentros cambian con la fecha. Una biblioteca o centro cultural puede ser un refugio cultural, siempre que exista una actividad abierta al público ese día.'),
('07 · Si viajas con niños','Alterna un museo apropiado para su edad con pausas, merienda y tiempos de descanso. Evita prometerles una navegación si el mar está complicado. Revisa accesibilidad de coches, baños, calefacción y distancias entre paradas antes de salir.'),
('08 · Si te cancelan una navegación','Solicita al operador la confirmación escrita de la cancelación, opciones de reprogramación y condiciones de devolución. No supongas que otro barco podrá salir si el motivo es meteorológico. Si debes volar pronto, elige un plan terrestre cercano y no sacrifiques el margen de traslado al aeropuerto.'),
('09 · Ropa y precauciones en la calle','Usa un cortaviento que ajuste bien, calzado antideslizante y capas térmicas cuando corresponda. En presencia de hielo camina sin prisa; con viento fuerte evita objetos sueltos y zonas expuestas. Si el transporte público o una carretera tiene restricciones, cambia el plan en lugar de insistir.'),
('10 · Tres planes alternativos','Plan cultural: Museo Regional más paseo patrimonial breve si las condiciones lo permiten. Plan gastronómico: una experiencia de cocina local y una exposición con horario confirmado. Plan familiar: un museo accesible, pausa en un café y regreso temprano. Elige el plan que minimice desplazamientos ese día.')
],'El secreto no es encontrar un lugar donde nunca sople viento: es construir un día interesante que no dependa del pronóstico. Guarda siempre un plan interior antes de reservar una salida al mar.','ciudad',('museo','borgatello','museos','municipio','fundacion'), 'Punta Arenas, Magallanes, Chile','Clima y alternativas')

add('guia','mes-a-mes','Punta Arenas mes a mes','Aquí las estaciones cambian la forma de viajar. No basta con elegir una fecha: hay que pensar en las horas de luz, el viento, las navegaciones y el ritmo que quieres darle a tu viaje.',[
('Enero · días largos','Es un mes para aprovechar recorridos al aire libre y excursiones con salida temprana. Organiza primero las actividades con cupo, como las navegaciones, y deja paseos urbanos para los espacios disponibles. Los días largos no significan calor de playa: lleva cortaviento y una capa de abrigo.'),
('Febrero · verano austral','Permite combinar ciudad, bosques y observación de fauna según operación. Es buena época para un viaje con varias jornadas, pero conviene reservar alojamiento y coordinar las salidas que dependan del mar. No dejes una navegación importante para las horas previas al vuelo.'),
('Marzo · cambio de ritmo','El viaje comienza a sentirse más otoñal. Puedes alternar los paisajes exteriores con museos y gastronomía. Confirma el calendario de cada operador: que una excursión aparezca en una guía no asegura que siga saliendo todos los días al final de la temporada.'),
('Abril · colores de otoño','Los bosques pueden ofrecer una experiencia distinta del verano. Las horas de luz se reducen, así que programa senderos por la mañana y lleva un regreso acordado. Las salidas a terreno deben ajustarse a la condición del camino y al estado del sendero.'),
('Mayo · plan urbano y pausas','Es momento de dar más espacio al patrimonio, las cafeterías y recorridos breves con abrigo. Consulta aperturas estacionales antes de viajar a un parque. Un día de cielo despejado puede aprovecharse sin convertirlo en una caminata exigente.'),
('Junio · llega el invierno','Las actividades necesitan más margen por hielo, frío y poca luz. Las Invernadas pueden incorporar el Chapuzón y otras celebraciones, pero cada edición tiene calendario propio. En 2026 el Chapuzón se programó para el 27 de junio; esa fecha no debe trasladarse automáticamente al año siguiente.'),
('Julio · Carnaval de Invierno','Es uno de los meses más vinculados a las celebraciones invernales. En 2026 el Carnaval se anunció para el 4 y 5 de julio. Para futuras visitas, espera el programa del municipio. Prepara capas, guantes y zapatos con buen agarre si vas a permanecer varias horas en la calle.'),
('Agosto · invierno con flexibilidad','Elige alojamiento con buena calefacción y deja alternativas interiores para cada jornada. El estado de las veredas puede importar tanto como la distancia del mapa. Para una excursión, pregunta por las condiciones reales del día y no solo por la duración habitual.'),
('Septiembre · tradiciones chilenas','Las Fiestas Patrias permiten acercarse a la comida y las costumbres locales. Las fondas, cierres y actividades dependen del programa de cada año. Si necesitas hacer compras o un trámite, revisa los horarios durante los feriados.'),
('Octubre · primavera y reaperturas','La temporada exterior vuelve a tomar fuerza de manera gradual. CONAF anunció para 2026–2027 aperturas de Pali Aike el 1 de octubre, Los Pingüinos el 15 y Laguna Parrillar el 16. Revisa siempre el estado vigente antes de desplazarte: una fecha de apertura no elimina los cierres por condiciones adversas.'),
('Noviembre · más tiempo afuera','Es una buena oportunidad para armar un viaje que combine patrimonio, naturaleza y navegación. Deja una jornada flexible y organiza actividades por sectores. Para Tierra del Fuego, coordina por separado la barcaza, la reserva y los trayectos terrestres.'),
('Diciembre · días extensos y fin de año','Aprovecha la luz para paseos largos y organiza con anticipación las cenas y los traslados de las fiestas. No cuentes con un espectáculo de fuegos artificiales si todavía no existe anuncio oficial. Para Año Nuevo conviene tener un plan concreto y un regreso reservado.'),
('Cómo elegir la temporada sin equivocarte','Para caminatas, privilegia meses con más horas de luz, pero considera el viento y la apertura efectiva de senderos. Para fauna, cada especie y cada operador tienen ventanas estacionales diferentes: pingüinos y otras especies no se observan de manera garantizada todo el año. Para un viaje cultural, Punta Arenas ofrece museos y patrimonio también fuera del verano. Evita escoger la fecha basándote únicamente en una foto de internet.'),
('Lo que cambia en el día a día','La luz disponible varía muchísimo entre las estaciones y modifica los horarios útiles de paseo. El viento puede ser notable incluso con cielo despejado, y en jornadas frías importa el estado de calzadas y aceras. Las excursiones por mar dependen de condiciones operativas, no solo de la lluvia. Revisa cada mañana pronóstico, restricciones y posibilidades de reprogramación.'),
('Reservas y presupuesto según el mes','En temporadas de más demanda conviene asegurar con antelación alojamiento y excursiones con cupos limitados. Fuera de temporada, confirma que los servicios realmente funcionen antes de reservar traslados no reembolsables. Los precios varían por fecha, proveedor y servicios incluidos: utiliza siempre cotizaciones actuales, especialmente para cruces y navegaciones.')],
'Yo elegiría la fecha por la experiencia que quieres vivir. Si los pingüinos son el motivo principal del viaje, confirma primero la temporada y la salida; después organiza el resto.',sources=('invernadas','parrillar','chile'),group='Cuándo venir')

add('guia','documentos','Documentos de entrada a Chile','Llegar con tus documentos ordenados te permite empezar el viaje con tranquilidad. Los requisitos dependen de tu nacionalidad, documento y situación migratoria; no existe una regla idéntica para todos los viajeros.',[
('Documento y autorización de ingreso','Comprueba con la autoridad chilena si debes viajar con pasaporte o si tu nacionalidad puede utilizar otro documento aceptado por un convenio vigente. Revisa también si necesitas autorización previa o visa. Una cédula válida para un país vecino no es automáticamente válida para todos los itinerarios.'),
('Qué conviene tener a mano','Guarda el alojamiento de la primera noche, información del regreso o continuación del viaje y comprobantes útiles para explicar tu visita si la autoridad los solicita. Conserva copias fuera del teléfono principal y revisa que los nombres de pasajes y documentos coincidan.'),
('Control SAG y alimentos','El control migratorio y el control sanitario son procesos distintos. Revisa la declaración SAG y declara los productos de origen animal o vegetal que correspondan. Si tienes dudas sobre un alimento, decláralo y entrégalo a evaluación; no asumas que por venir sellado o comprado en un aeropuerto está autorizado.'),
('Si vienes desde Argentina','Verifica el paso fronterizo habilitado, sus horarios y la documentación de todos los pasajeros. Si conduces, consulta además las exigencias del vehículo y del contrato de arriendo. Un itinerario por tierra puede incluir controles diferentes a los de un vuelo nacional desde Santiago.'),
('Antes del vuelo: lista documental','Comprueba vigencia del documento, nombre exactamente como figura en la reserva, autorización migratoria cuando corresponda y eventuales requisitos de tránsito. Si el viaje combina Chile y Argentina, verifica por separado las reglas de cada país; las condiciones no son intercambiables.'),
('Escala en Santiago y conexión a PUQ','Si llegas desde el extranjero a Chile y conectas a un vuelo doméstico, revisa dónde se completan migraciones, equipaje y aduana según tu itinerario. Deja tiempo suficiente para conexiones y sigue las instrucciones de la aerolínea y del aeropuerto.'),
('Documentos para arrendar un vehículo','La arrendadora puede exigir licencia de conducir vigente, tarjeta para garantía y documentación adicional. Para salir del país con un vehículo de alquiler se requieren verificaciones especiales; consulta por escrito antes de reservar.'),
('Copias de respaldo y privacidad','Lleva copia digital segura de documentos y reservas, pero conserva los originales exigidos por transportistas y autoridades. Evita enviar fotografías de pasaporte a contactos que no hayas verificado y no publiques sus datos en redes sociales.')],
'Antes de pagar el viaje revisaría los requisitos por nacionalidad. Y al preparar la mochila separaría los documentos del resto del equipaje, para no buscarlos en medio del control.',sources=('visas','sag','migraciones'),group='Antes de viajar')

add('guia','consulados','Consulados y asistencia consular','La asistencia consular depende de tu nacionalidad y del tipo de problema. Un consulado honorario no siempre puede emitir documentos de emergencia ni realizar los mismos trámites que una sección consular.',[
('Cómo encontrar la oficina correcta','Utiliza el directorio oficial de tu cancillería o embajada en Chile. Comprueba la jurisdicción sobre Magallanes, los horarios de atención y el canal de urgencias. No des por vigente un teléfono publicado hace años en un directorio comercial.'),
('Pérdida de documentos','Ve a un lugar protegido, conserva las copias disponibles y consulta a tu representación sobre la denuncia y el documento que necesitas para continuar el viaje. La aerolínea y la frontera pueden tener exigencias distintas: emitir un documento no significa que todo el itinerario quede automáticamente autorizado.'),
('Qué información preparar','Ten nombre completo, nacionalidad, número de documento si lo conservas, dirección de alojamiento, contacto de confianza y explicación breve de lo ocurrido. Si necesitas ayuda fuera del horario de oficina, distingue una urgencia consular de una consulta administrativa.'),
('Qué puede resolver el consulado','Puede orientarte dentro de sus atribuciones. No debe asumirse que pagará multas, hospitalizaciones, pasajes o deudas. Para atención médica utiliza el sistema de urgencia y la asistencia de tu seguro; para un delito, corresponde acudir a la autoridad local.'),
('Embajadas y consulados fuera de Magallanes','No todos los países mantienen consulado profesional en Punta Arenas. En algunos casos el trámite corresponde a una oficina en Santiago o a una representación honoraria con atribuciones limitadas. Consulta el directorio oficial de tu país antes de desplazarte.'),
('Si necesitas viajar de urgencia','Contacta primero al consulado sobre pasaporte de emergencia o salvoconducto y luego verifica con la aerolínea o transportista que ese documento sea aceptado en todas las escalas y fronteras. No compres un trayecto no reembolsable basándote en una suposición.'),
('Situaciones médicas y hospitalización','Prioriza la atención sanitaria y activa la asistencia del seguro. Una representación consular puede orientar y contactar familiares dentro de sus competencias, pero no reemplaza la atención médica ni garantiza cubrir gastos.'),
('Asistencia en caso de detención o delito','Comunícate con las autoridades locales según corresponda y pide información para contactar a tu consulado. La representación consular no sustituye a un abogado ni interviene para anular procesos legales; consulta sus servicios reales.')],
'Guardaría el contacto oficial de mi representación antes de viajar. Una captura de pantalla y una copia en papel ayudan si el teléfono se queda sin batería.',sources=('visas',),group='Antes de viajar')

add('guia','viajar-con-menores','Viajar con menores a Punta Arenas','El viaje familiar comienza antes de llegar al aeropuerto. La documentación de niños y adolescentes depende de quién los acompaña, su nacionalidad y residencia, y de si el trayecto incluye entrar o salir de Chile.',[
('Revisa todo el recorrido','Distingue un vuelo nacional de una salida internacional. Un viaje desde Punta Arenas a Argentina o un circuito que cruce la frontera requiere revisar los documentos de cada menor. Confirma el caso específico con la autoridad antes de comprar servicios no reembolsables.'),
('Autorizaciones y vínculo familiar','Si viaja con uno solo de sus progenitores, con terceros o sin acompañante, pueden corresponder autorizaciones y documentos que acrediten el vínculo. Las reglas de legalización o apostilla deben verificarse según dónde se emite el documento. Una fotografía del permiso puede no reemplazar el original exigido.'),
('Condiciones del transporte','Consulta a la aerolínea, empresa de bus o navegación por las condiciones para menores, sillas infantiles y restricciones de edad. En excursiones marítimas pregunta también por tallas de chalecos y la posibilidad de cancelación por condiciones del mar.'),
('Un día cómodo en la ciudad','Alterna un recorrido corto con una parada interior. Lleva ropa de recambio, colación permitida, agua y abrigo que puedan quitarse por capas. El viento cambia la sensación térmica y una caminata sencilla para adultos puede resultar agotadora para un niño pequeño.'),
('Volando con bebés y niños','Antes del vuelo revisa edad mínima, equipaje infantil, coche, silla, alimentos y documentación con la aerolínea. Para menores no acompañados pueden existir servicios y restricciones especiales que deben reservarse anticipadamente.'),
('Cruces hacia Tierra del Fuego y Argentina','Un itinerario con fronteras internacionales exige revisar autorizaciones específicas del menor, además de la documentación del adulto responsable y del vehículo si corresponde. Consulta controles y documentos requeridos antes de planear una excursión internacional.'),
('Elegir excursiones según edad','Pregunta por duración, disponibilidad de baños, abrigo, chalecos adecuados, accesibilidad y condiciones de reprogramación. Una navegación con viento o una caminata larga puede no ser apropiada para todos los niños, aunque el atractivo sea familiar.'),
('Preparar un día de clima cambiante','Lleva capas, guantes según temporada, ropa seca y una actividad alternativa bajo techo. En invierno considera el estado de veredas y los tiempos de luz; no conviertas una jornada familiar en una carrera entre atracciones.')],
'Yo resolvería los papeles con tiempo y llevaría los originales organizados por persona. Después armaría jornadas cortas: disfrutar juntos vale más que completar una lista.',sources=('menores',),group='Antes de viajar')

add('guia','permanencia-y-extension','Permanencia y extensión en Chile','El plazo que puedes permanecer en Chile debe leerse en tu autorización de ingreso. No lo calcules por lo que le permitieron a otra persona ni confundas turismo con residencia.',[
('Revisa el plazo otorgado','La Permanencia Transitoria contempla una estadía limitada. Conserva el registro de ingreso y comprueba la fecha de vencimiento aplicable a tu caso. El documento vigente y el permiso de permanencia cumplen funciones distintas.'),
('Si necesitas quedarte más tiempo','SERMIG dispone de un procedimiento de prórroga a través de su portal digital. Revisa las condiciones, documentos y costo vigente directamente en la ficha oficial, y solicita el trámite dentro del plazo correspondiente. No esperes a que termine tu autorización para recién informarte.'),
('Prórroga no significa aprobación automática','Presentar una solicitud no equivale a poder ignorar el vencimiento o trabajar. Sigue el procedimiento y conserva comprobantes. Las actividades remuneradas tienen reglas específicas que no se resuelven con una reserva de alojamiento.'),
('Antes de salir o volver a entrar','Si estás tramitando una extensión o tienes una situación especial, consulta cómo afecta una salida del país. No tomes una excursión internacional como un método para renovar automáticamente tu estadía.'),
('No confundas duración de viaje con plazo migratorio','La reserva de hotel, el pasaje de regreso y los días que planeas visitar la Patagonia no fijan por sí mismos tu autorización. Revisa la permanencia que efectivamente te otorgaron y anótala con suficiente margen.'),
('Documentos y seguimiento digital','Antes de solicitar una prórroga consulta el portal del Servicio Nacional de Migraciones para identificar documentos, formularios, pago si corresponde y comprobantes válidos. Conserva confirmaciones oficiales y revisa el estado por canales autorizados.'),
('Visita a Argentina durante tu estancia','Si tu itinerario combina Puerto Natales o Punta Arenas con El Calafate o Ushuaia, revisa tanto la salida de Chile como los requisitos de ingreso y posterior retorno. Cruzar la frontera no garantiza extender automáticamente un permiso.'),
('Dónde buscar ayuda confiable','En caso de dudas de vencimiento, actividades permitidas o situación migratoria, utiliza SERMIG y canales consulares oficiales. No confíes en consejos de viajeros que describan experiencias con permisos o nacionalidades distintas.')],
'Anotaría el vencimiento con una alerta varios días antes. Para una decisión migratoria, la respuesta que cuenta es la del servicio competente para tu caso.',sources=('migraciones','prorroga'),group='Antes de viajar')

add('guia','viajar-solo','Viajar solo o sola a Punta Arenas','Punta Arenas permite combinar caminatas urbanas, cultura y excursiones compartidas. Para disfrutarla a tu ritmo, deja resueltos el alojamiento, los regresos y una alternativa por si el clima cambia.',[
('Elegir una base práctica','Si es tu primera visita, compara alojamientos cercanos a los lugares que visitarás y a tus puntos de salida. Comprueba la recepción si llegas tarde, la calefacción y el acceso con equipaje. Una habitación barata lejos de todo puede terminar costando más en transporte.'),
('Llegar con un plan sencillo','Guarda la dirección y coordina cómo llegar desde el aeropuerto o el bus. La primera jornada puede ser solo plaza, una caminata corta y una comida. Después de varias horas viajando no necesitas sumar inmediatamente una excursión exigente.'),
('Conocer gente sin perder independencia','Las visitas guiadas, excursiones grupales y espacios comunes del alojamiento permiten conversar y compartir experiencias. Confirma qué incluye cada salida, quién la opera y dónde termina. Viajar solo no significa contratar todo ni tampoco resolver siempre todo sin apoyo.'),
('Caminar y volver por la noche','Elige un destino concreto y define el regreso antes de salir. Revisa matrícula y conductor al usar una aplicación, pide el viaje desde un lugar protegido y comparte el recorrido si lo consideras útil. No dependas de conseguir un vehículo inmediato en un lugar remoto.'),
('Senderos y lugares apartados','Comparte el itinerario, la hora de retorno y el punto de partida con alguien de confianza. Revisa dificultad, señal, estado del sendero y condiciones meteorológicas. Para una ruta que supera tu experiencia, busca guía y equipamiento apropiados; un mapa descargado no reemplaza preparación.'),
('Cuidar dinero y documentos','Separa una tarjeta de respaldo, conserva copias digitales y evita llevar todas tus pertenencias en la misma bolsa. Ten a mano los datos de tu seguro y alojamiento. Si cambias el plan del día, actualiza a la persona que conoce tu recorrido.'),
('Un itinerario equilibrado','Puedes dedicar un día al centro, mirador y costanera; otro a un museo y patrimonio; y una jornada flexible a una excursión. Intercambia los días según las condiciones. Así una cancelación de navegación no deja todo el viaje sin alternativas.'),
('Dónde alojarte si viajas sin compañía','Busca una ubicación desde la que puedas regresar de manera sencilla por la noche y consulta horarios de recepción, calefacción y condiciones de cancelación. Un hostal puede facilitar encuentros, mientras que un alojamiento independiente puede resultar cómodo si prefieres tranquilidad. Lee reseñas recientes sobre la zona y la comunicación con el anfitrión.'),
('Excursiones compartidas para conocer gente','Las visitas guiadas y excursiones de grupo pueden ser una alternativa para compartir costos y conversar con otros viajeros. Pregunta por la modalidad de salida, idioma de la guía, punto de recogida y número mínimo de participantes. No confundas una reserva individual con una excursión privada incluida.'),
('Comer solo también puede ser parte del viaje','Una cafetería céntrica o un restaurante con mesas pequeñas puede resultar cómodo para una pausa sin prisas. Lleva tus preferencias gastronómicas claras y reserva si se trata de un lugar pequeño en una fecha muy demandada. Revisa horarios y ubicación antes de alejarte del alojamiento por la noche.'),
('Plan para un día de clima difícil','Mantén dos opciones interiores que no dependan de un traslado largo, como un museo o una actividad cultural con horarios confirmados. Si una navegación se cancela, coordina devolución o nueva fecha antes de reorganizar tu alojamiento. Evita salir solo a senderos expuestos para compensar una excursión cancelada.'),
('Conexión, emergencias y regreso seguro','Descarga mapas sin conexión, carga el teléfono antes de salir y lleva una batería portátil si el recorrido será largo. Comparte tu ruta y hora estimada de regreso con alguien de confianza en excursiones apartadas. Comprueba cobertura y alternativas de transporte antes de ir a lugares aislados; ante riesgo climático, prioriza regresar.')],
'Yo viajaría con un plan flexible, pero nunca sin regreso. Dejaría avisado el recorrido antes de una caminata y conservaría una jornada libre para reprogramar lo importante.',sources=('chile','sernatur'),group='Antes de viajar')

add('guia','seguro-y-salud','Seguro y salud','Para un viaje a Magallanes conviene pensar en la atención médica y también en dónde estarás cuando la necesites. La cobertura urbana y la de una excursión remota pueden ser muy diferentes.',[
('Qué comparar en una póliza','Revisa atención médica, hospitalización, asistencia de emergencia, evacuación y repatriación, además de exclusiones, franquicias y condiciones preexistentes. Si harás trekking o navegación, confirma que esas actividades están incluidas y bajo qué límites.'),
('Cómo pedir asistencia','Guarda el número de tu compañía y el procedimiento para abrir un caso. Cuando sea posible, consulta antes de una atención no urgente para saber a qué prestador acudir y cómo pagar. En una urgencia real, prioriza recibir ayuda.'),
('Medicamentos habituales','Viaja con reserva razonable para tu itinerario, envases identificados y la documentación médica que corresponda. Consulta las restricciones de ingreso si llevas medicamentos sujetos a control. El nombre comercial puede cambiar entre países.'),
('Prepararse para el frío','Usa capas secas y calzado apropiado; cambia prendas mojadas y busca abrigo si el malestar aumenta. Para recomendaciones individuales sobre enfermedades, embarazo o capacidad física, consulta a tu profesional de salud antes de la salida.'),
('Elegir cobertura para navegación y trekking','Lee exclusiones sobre actividades de aventura, rescate y evacuación en áreas remotas. Solicita confirmación por escrito si la actividad concreta está cubierta; un seguro de viaje genérico puede no incluir todos los escenarios.'),
('Atención de urgencia en Chile','En una emergencia médica se puede contactar al SAMU al 131. Ten a mano ubicación, teléfono y descripción del problema. Para consultas no urgentes verifica previamente prestadores habilitados y la modalidad de pago de tu seguro.'),
('Salud en viajes largos y traslados','Organiza pausas, hidratación y abrigo en trayectos terrestres prolongados. Si requieres medicación regular, distribuye cantidades de respaldo y consulta anticipadamente la documentación necesaria para transportarla.'),
('Antes de viajar con una condición de salud','Si necesitas equipamiento médico, oxígeno, medicamentos de control o adaptaciones de movilidad, coordina tu viaje con tu profesional de salud y con los transportistas. La guía turística no reemplaza una indicación médica individual.')],
'No elegiría el seguro solo por el precio. Preguntaría expresamente qué pasa si necesito asistencia lejos de la ciudad.',sources=('salud','vacunas'),group='Antes de viajar')

add('guia','vacunas','Vacunas y preparación sanitaria','La preparación sanitaria debe considerar tu edad, antecedentes, origen e itinerario completo. Una visita urbana a Punta Arenas y un viaje internacional con varias escalas no son el mismo escenario.',[
('Revisar el calendario personal','Antes del viaje consulta si tienes al día tu esquema de inmunizaciones y si corresponde alguna medida adicional para tu situación. El frío de la Patagonia no reemplaza la prevención de infecciones respiratorias.'),
('Requisito de entrada y recomendación','Distingue lo que una autoridad exige para ingresar de lo que un profesional recomienda para protegerte. No uses requisitos antiguos de pandemia ni listas de otro país como si fueran condiciones actuales de Chile.'),
('Si viajas con niños o personas vulnerables','Consulta con anticipación para disponer de tiempo si se necesita actualizar una vacuna. Lleva los antecedentes importantes y revisa la disponibilidad de atención durante el viaje. No improvises dosis o medicamentos a partir de una guía turística.'),
('Preparación sanitaria según país de origen','Verifica en fuentes oficiales chilenas si existen requisitos especiales asociados a tu itinerario y consulta con profesionales de salud tus vacunas recomendadas. Una escala internacional o una extensión del viaje a otro país puede cambiar las recomendaciones.'),
('Frío, lluvia y problemas respiratorios','Consulta las previsiones de frío y viento para preparar abrigo, ropa seca y medicamentos que ya utilices conforme a indicación profesional. Evita interpretar consejos generales de turismo como sustituto de un diagnóstico o tratamiento médico.'),
('Botiquín y medicación personal','Lleva un pequeño botiquín acorde a tus necesidades, medicación habitual en su empaque y recetas cuando correspondan. Para tratamientos sujetos a control comprueba las condiciones de transporte y entrada al país antes de viajar.'),
('Niños y viajeros con condiciones especiales','Pregunta con anticipación al pediatra o profesional tratante sobre necesidades particulares. Consulta accesibilidad del alojamiento y los medios de transporte, y conserva documentación de alergias o tratamientos esenciales de forma segura.')],
'Guardaría el carnet de vacunas junto a los documentos y consultaría con tiempo. Las indicaciones personales deben venir de un profesional de salud.',sources=('vacunas','salud'),group='Antes de viajar')

add('guia','dinero-y-tarjetas','Dinero y tarjetas','Organiza tus pagos en pesos chilenos y lleva una alternativa si tu tarjeta o teléfono falla. Lo práctico es combinar medios de pago y revisar los costos antes de usarlos.',[
('Moneda y presupuesto','En Chile se usa el peso chileno, identificado como CLP. El símbolo $ aparece en las cartas y comercios: confirma siempre la moneda si comparas un servicio internacional. Separa presupuesto para transporte, comida, entradas y un margen de reprogramación.'),
('Tarjetas extranjeras','Consulta a tu banco por compras internacionales, comisiones y bloqueos. En un terminal, revisa el monto y la moneda antes de autorizar. La aceptación puede variar entre comercios, excursiones y servicios pequeños.'),
('Efectivo de respaldo','Lleva billetes de denominación útil para gastos menores. Al retirar de un cajero, lee las comisiones que muestra y considera las de tu banco. No publiques ni compartas los datos de tu tarjeta para confirmar una reserva.'),
('Antes de contratar un servicio','Pide por escrito el total, qué incluye, política de cancelación y comprobante. En excursiones sujetas al tiempo, distingue cancelación del operador, cambio de fecha y desistimiento del pasajero.'),
('Cambiar moneda sin sorpresas','Compara la tasa final y las comisiones antes de cambiar divisas. No confundas el precio de compra con el de venta de moneda extranjera. Usa establecimientos autorizados y solicita comprobante; no lleves cantidades importantes de efectivo a excursiones.'),
('Cajeros automáticos','Retira dinero en un lugar que te resulte seguro, preferiblemente durante el día. El cajero puede anunciar una comisión y tu banco sumar otra; cancela si la operación no te conviene. Ten una tarjeta alternativa y no dependas de encontrar cajeros fuera de Punta Arenas.'),
('Pagar excursiones y reservas','Verifica el nombre comercial, moneda, precio total, señal o anticipo, servicios incluidos y condiciones de reembolso por mal tiempo. Evita transferencias a destinatarios desconocidos sin documentación de respaldo.'),
('Presupuesto diario y gastos olvidados','Calcula alojamiento, alimentación, transporte, entradas y excursiones por separado. Agrega seguro, datos móviles, propinas voluntarias y margen para traslados extraordinarios. Los valores concretos deben verificarse y fecharse antes de publicarlos.'),
('Qué hacer si una tarjeta falla','Usa otra tarjeta o efectivo disponible, contacta al banco por su canal oficial y comprueba si existe un bloqueo internacional. No compartas claves, códigos de verificación ni números completos de la tarjeta con intermediarios.')],
'Yo separaría una tarjeta de respaldo y una pequeña reserva en efectivo. No saldría a una excursión dependiendo de una única aplicación de pago.',sources=(),group='Conectado y preparado')

add('guia','internet-y-esim','Internet, SIM y eSIM','La conexión ayuda en la ciudad, pero no debe ser tu único recurso para orientarte en carretera o senderos. Resuelve los datos móviles antes de necesitarlos y guarda información sin conexión.',[
('Comparar opciones','Puedes evaluar roaming de tu operador, una SIM local o una eSIM compatible. Revisa datos incluidos, vigencia, red utilizada y si el servicio permite compartir internet. Algunas eSIM son solo de datos y no incluyen un número para llamadas.'),
('Compatibilidad del teléfono','Comprueba que el equipo esté liberado y admita la opción elegida. Para equipos extranjeros que usan SIM local, Multibanda/SAE informa sobre la inscripción necesaria para seguir operando después de los primeros 30 días de activación en red chilena.'),
('Fuera de la ciudad','No presupongas cobertura continua en islas, estepa o rutas del sur. Descarga mapas, reservas y contactos. Si realizas una actividad remota, pregunta al operador cómo se comunica ante una emergencia.'),
('Batería y respaldo','Lleva batería externa, cable y protección contra humedad. Guarda también una dirección escrita: depender de un único teléfono puede complicar un traslado incluso si contrataste muchos datos.'),
('Qué elegir para una estadía corta','Si visitas solo Punta Arenas durante pocos días, compara paquetes de roaming y eSIM antes del vuelo. Si piensas ir a Puerto Natales, Tierra del Fuego o rutas remotas, comprueba mapas de cobertura por operador y no asumas que toda la Patagonia tendrá señal.'),
('Cómo instalar una eSIM con calma','Comprueba compatibilidad y desbloqueo del móvil, conserva el código de instalación, sigue las instrucciones del proveedor y prueba la conexión en un lugar con wifi. Revisa qué línea usa datos y si el paquete permite llamadas o únicamente internet.'),
('Wifi y seguridad digital','Las redes de alojamientos y cafeterías pueden servir para descargar mapas, pero evita compartir información bancaria sensible en conexiones desconocidas. Verifica el nombre de la red con el establecimiento y mantén el sistema actualizado.'),
('Cruzar a Argentina','Si tu recorrido incluye la Patagonia argentina, comprueba si tu paquete cubre ambos países. Una eSIM válida en Chile no necesariamente incluye Argentina y pueden aplicarse tarifas de roaming distintas.'),
('Señal y emergencias en lugares apartados','Descarga mapas y pasajes, lleva batería externa y comparte horarios de regreso. Si una excursión transcurre sin cobertura, consulta qué sistema de comunicación utiliza el operador; tener teléfono no sustituye el equipamiento de seguridad.')],
'Descargaría el mapa de Magallanes y las reservas antes de salir del alojamiento. Tener internet comprado no garantiza señal en todo el recorrido.',sources=('imei',),group='Conectado y preparado')

add('guia','accesibilidad','Accesibilidad en Punta Arenas','La accesibilidad se verifica para una necesidad concreta. Una rampa en el edificio no garantiza que el baño, el vehículo, la ruta de acceso y toda la actividad resulten utilizables.',[
('Alojamiento y trayecto real','Solicita medidas y fotografías del acceso, ascensor, ducha y espacio junto a la cama si los necesitas. Revisa también la vereda y la pendiente de la calle. La cercanía en el mapa no refleja siempre el esfuerzo del trayecto.'),
('Aeropuerto y transporte','Coordina la asistencia con la aerolínea y consulta los puntos de encuentro del aeropuerto. Para el traslado terrestre, confirma el tipo de vehículo y las dimensiones que acepta, además de si la ayuda incluye subir y bajar equipaje o silla.'),
('Museos y naturaleza','Pregunta por el recorrido completo, superficies, descansos y baños. La Reserva Nacional Magallanes describe un sendero para movilidad reducida; su estado y disponibilidad deben confirmarse. La Reserva Pingüino Rey informa sobre una silla adaptada para terreno natural.'),
('Navegaciones y clima','Consulta rampas de embarque, escalones y asistencia a bordo antes de reservar. Las mareas y el movimiento pueden alterar el acceso. En invierno, el hielo puede cambiar la viabilidad de un recorrido urbano que en verano parece sencillo.'),
('Planificar una ruta sin barreras','Evalúa pendiente, ancho de aceras, cruces, baños, accesos y distancia total, además del atractivo turístico. Pide datos y fotos actuales del trayecto; el viento y el hielo pueden alterar las condiciones de una ruta habitual.'),
('Sillas de ruedas y traslados privados','Confirma las dimensiones y peso admitidos por el vehículo, si dispone de anclajes y si permite viajar sentado en la silla con seguridad. No presupongas que cualquier taxi o transferencia turística está adaptado.'),
('Personas con discapacidad visual o auditiva','Consulta a los museos y operadores por audioguías, material descriptivo, subtítulos, interpretación o apoyos disponibles. No prometas accesibilidad sensorial sin verificar el recurso concreto y la fecha de visita.'),
('Itinerarios tranquilos para mayores y familias','Alterna actividades cortas con pausas y lugares protegidos del clima. Pregunta por asientos, calefacción, ascensores, baños y asistencia durante embarques. Cada persona tiene necesidades diferentes y se debe confirmar con el prestador.'),
('Cómo solicitar información útil','Al escribir a un establecimiento explica qué necesitas: entrada sin escalón, ancho mínimo de puerta, baño con barras, ascensor o transporte adaptado. Pide respuesta específica y actualizada en vez de aceptar únicamente la etiqueta accesible.')],
'Yo preguntaría por el recorrido desde la puerta del alojamiento hasta el final de la actividad, no solo si el lugar se anuncia como accesible.',sources=('puq-servicios','reserva','rey'),group='Conectado y preparado')

add('guia','aeropuertos','Aeropuerto de Punta Arenas · PUQ','El Aeropuerto Presidente Carlos Ibáñez del Campo es la principal puerta aérea de Punta Arenas. Identifícalo por su código PUQ y organiza el tramo hasta tu alojamiento antes de llegar.',[
('Ubicación y llegada','El sitio del aeropuerto sitúa el terminal en el km 20,5 de la Ruta 9 Norte. El trayecto a la ciudad requiere transporte: no es una llegada a pie al centro. Guarda tu dirección completa y el nombre del alojamiento.'),
('Elegir el traslado','Compara servicios oficiales del aeropuerto, taxi y traslado previamente contratado. Confirma el precio vigente, cantidad de pasajeros y equipaje incluido. Si usas una aplicación, revisa disponibilidad y punto de encuentro en el momento.'),
('Si sigues a Puerto Natales','Comprueba si el servicio que contrataste pasa por el aeropuerto o sale de una oficina en la ciudad. No supongas que todos los buses hacen la misma parada. Deja margen para equipaje, retrasos y coordinación.'),
('El regreso al aeropuerto','Confirma la hora de presentación con tu aerolínea y añade margen terrestre. Si el día anterior tienes una excursión marítima, considera qué ocurre si se retrasa. Para movilidad reducida, coordina la asistencia de manera anticipada.'),
('Equipaje, servicios y conectividad','Comprueba las políticas de tu aerolínea y las instalaciones efectivamente disponibles en el terminal. Si necesitas datos móviles, coordínalos antes de viajar y descarga dirección y reservas para consultar sin conexión.'),
('Vuelo de madrugada o llegada nocturna','Coordina recepción del alojamiento y traslado con anticipación. Pregunta por el punto exacto de encuentro y las condiciones si tu vuelo se retrasa; no presupongas que habrá siempre un vehículo disponible.'),
('Accesibilidad y necesidades especiales','Solicita asistencia a la aerolínea y al aeropuerto según sus procedimientos. Informa si viajas con silla de ruedas, equipamiento médico, coche infantil o equipaje voluminoso, y verifica las características del vehículo de traslado.')],
'Yo dejaría reservado el traslado si llego tarde o con mucho equipaje. Y pediría el punto de encuentro por escrito.',sources=('puq','puq-servicios'),group='Llegar y moverse')

add('guia','terminales-de-bus','Terminales y buses interurbanos','En Punta Arenas importa saber desde qué oficina, terminal o paradero sale tu empresa. No basta con escribir “terminal de buses” en el mapa.',[
('Antes de comprar','Compara destino, fecha, lugar de salida y de llegada, equipaje y condiciones de cambio. Para Puerto Natales revisa si el servicio sale del centro o incluye una parada que te convenga. Conserva el comprobante accesible sin conexión.'),
('Confirmar el embarque','El día anterior verifica la dirección exacta y la anticipación exigida por la empresa. Si vas en taxi o aplicación, escribe el nombre del operador y la dirección, no un terminal genérico.'),
('Viajes internacionales','Para Argentina, confirma documentos, control fronterizo, equipaje y productos que puedes transportar. Los horarios pueden verse afectados por controles y condiciones de ruta. No unas este viaje con un vuelo de margen mínimo.'),
('Con niños o equipaje especial','Consulta condiciones para menores, sillas, bicicletas o maletas adicionales antes de pagar. La compra de un asiento no implica aceptar automáticamente todos los bultos.'),
('Puerto Natales: organizar la conexión','Identifica el operador, dirección exacta de embarque y lugar de llegada antes de comprar. Calcula varias horas de trayecto terrestre dependiendo del servicio y las condiciones viales. Si continúas hacia Torres del Paine, verifica que el siguiente transporte salga de un punto compatible.'),
('Equipaje y servicios de la empresa','Comprueba límite de maletas, equipaje especial, asientos y cambios o devoluciones. No presupongas que el operador dispone de guarda equipaje, baños o una sala de espera en cada punto de salida.'),
('Clima, hielo y planificación','En invierno y durante episodios de viento fuerte verifica avisos oficiales y la operación de tu bus. Evita conexiones con margen mínimo entre un recorrido interurbano y el aeropuerto.'),
('Conexiones a Tierra del Fuego','Algunas rutas involucran transbordadores y pueden cambiar según condiciones de operación. Comprueba si el pasaje incluye los tramos marítimos, puntos de encuentro y cómo volver si se altera una salida.')],
'Guardaría una captura del punto de salida. Equivocarse de oficina puede ser más fácil que equivocarse de ciudad.',sources=('natales','chile'),group='Llegar y moverse')

add('guia','cruceros','Cruceros en Punta Arenas','Una escala en Punta Arenas se organiza desde el terminal y el horario real de regreso a bordo. El puerto, el sistema de desembarco y el viento determinan cuánto tiempo tendrás en tierra.',[
('Identifica tu terminal','EPAustral opera instalaciones portuarias con condiciones distintas. Arturo Prat está vinculado al sector céntrico; José de los Santos Mardones atiende también grandes naves en el sector norte. La naviera confirma el punto de desembarco y si hay acercamiento.'),
('Si desembarcas en tender','Cuando se utilizan embarcaciones auxiliares, los tiempos de bajar y volver pueden variar. No calcules una excursión usando únicamente el horario de llegada del crucero.'),
('Un recorrido urbano posible','Con tiempo suficiente, puedes organizar plaza, patrimonio exterior, una pausa para comer y costanera. El mirador requiere considerar la pendiente. Elige pocas paradas que puedas disfrutar y adapta el recorrido al clima.'),
('Antes de salir lejos','Una navegación adicional o una salida a Tierra del Fuego no debe asumirse compatible con cualquier escala. Verifica duración completa, condiciones de cancelación y margen de regreso exigido por tu naviera.'),
('La escala empieza por el horario de regreso','Antes de bajar confirma a qué hora debes estar nuevamente a bordo y desde qué terminal o muelle se realizará el embarque. Separa tiempo para controles, transporte y cambios por viento; perder el barco puede ser costoso.'),
('Recorrido breve por el centro','En una escala corta prioriza un paseo concentrado por la Plaza Muñoz Gamero, calles patrimoniales y la costanera si las condiciones lo permiten. No programes lugares distantes sin transporte organizado y un cálculo realista de tiempos.'),
('Qué hacer si llueve o sopla mucho viento','Elige museos o cafeterías cuya apertura hayas confirmado. Evita paseos expuestos de larga duración y mantén comunicación con la naviera o el operador del traslado si cambia el puerto o la hora de desembarco.'),
('Excursiones desde el crucero','Contrata una actividad solo después de comprobar duración total, recogida y regreso al puerto. Fuerte Bulnes o paseos a las afueras necesitan planificación distinta a una visita céntrica; las navegaciones de fauna pueden no ser adecuadas para escalas breves.'),
('Movilidad reducida y equipaje','Consulta accesibilidad desde la pasarela de desembarco hasta el vehículo. Si necesitas guardar equipaje, confirma previamente una consigna real y el horario de retiro; no presupongas instalaciones disponibles en el puerto.'),
('Comer y comprar antes de regresar','Si tienes margen, reserva tiempo para un plato local o recuerdos de Punta Arenas, pero comprueba horario del local y distancia al muelle. Evita usar todo el tiempo disponible en una compra lejana.')],
'Yo anotaría la hora límite de regreso y tendría claro qué hora utiliza el barco. Haría el recorrido desde ese límite hacia atrás.',sources=('epa',),group='Llegar y moverse')

add('guia','como-moverse','Cómo moverse por Punta Arenas','El centro se puede explorar por sectores, mientras que compras, aeropuerto y naturaleza requieren planificar distancias. No todos los lugares destacados están dentro del área urbana.',[
('Caminar por el centro','Agrupa plaza, edificios patrimoniales, comida y costanera en un mismo paseo. Para subir al Cerro de la Cruz considera desnivel y clima. En invierno presta atención al hielo y al estado de las superficies.'),
('Micros y colectivos','Las micros siguen recorridos urbanos; los colectivos comparten viaje en una ruta determinada. Verifica el sentido y que pasen por tu destino antes de subir. Un colectivo no funciona como un taxi de recorrido libre.'),
('Taxi y aplicaciones','Son útiles para equipaje, llegadas y regresos nocturnos. Confirma precio o tarifa aplicable y revisa el vehículo si lo pediste por aplicación. En lugares alejados conviene acordar el retorno.'),
('Para salir de la ciudad','Reserva, Faro San Isidro, Pali Aike y Tierra del Fuego necesitan su propia logística. Compara traslado, tour o auto y pregunta por el estado de caminos. Tener auto no elimina las restricciones de acceso.'),
('Planifica un paseo por sectores','Agrupa la Plaza Muñoz Gamero, Calle Bories y edificios patrimoniales en un recorrido céntrico; deja una segunda salida para costanera o miradores según viento y movilidad. Revisar desniveles ayuda a evitar trayectos incómodos.'),
('Cómo combinar buses y colectivos','Revisa rutas y sentidos en fuentes actualizadas antes de salir. Los colectivos pueden tener recorridos habituales y operar de manera diferente a las micros; confirma con el conductor si el servicio pasa por tu destino.'),
('Equipaje, noche y regreso','Para una llegada nocturna, lluvia o varias maletas puede convenirte coordinar taxi o traslado con anticipación. En sitios alejados de la ciudad no confíes en conseguir regreso mediante una aplicación sin haber comprobado cobertura y disponibilidad.'),
('Movilidad accesible','No todos los vehículos y paradas tienen las mismas condiciones de accesibilidad. Antes de reservar pregunta específicamente por espacio para silla de ruedas, rampas, ayuda para subir y disponibilidad real del servicio.')],
'Yo organizaría cada día por un sector. Ahorras trayectos y puedes cambiar el orden sin rehacer todo el viaje.',sources=('chile','uber','red'),group='Llegar y moverse')

add('guia','maleta-y-clima','Maleta y clima austral','La clave es vestirse por capas y protegerse del viento. Una maleta útil para Punta Arenas debe permitir adaptarse durante el día sin cargar ropa innecesaria.',[
('Sistema de capas','Combina una primera capa cómoda, una de abrigo y una exterior cortaviento o impermeable según la actividad. Elige prendas que puedas poner y quitar con facilidad. Una chaqueta pesada no siempre resuelve por sí sola humedad y viento.'),
('Pies, manos y cabeza','Lleva calzado de buen agarre, calcetines de recambio, gorro y guantes según la época. Para senderos pregunta por el terreno: zapatos urbanos y botas de trekking cumplen funciones diferentes.'),
('Mochila diaria','Incluye agua, una colación adecuada al recorrido, batería, documentos necesarios y una bolsa para mantener seco lo importante. Protege cámara y teléfono. No cuelgues objetos que el viento pueda llevarse.'),
('Cada actividad pide algo distinto','Para navegar revisa indicaciones del operador; para trekking, dificultad y equipamiento. Consulta pronóstico local y avisos antes de salir. No uses una temperatura media mensual como pronóstico de la jornada.'),
('Calzado y protección frente al viento','Elige calzado con suela de buen agarre para caminatas urbanas y senderos. Un abrigo cortaviento y capas térmicas son más versátiles que depender de una sola prenda gruesa. Una gorra o capucha bien ajustada evita perder accesorios en días de viento.'),
('Qué llevar para una navegación','Guarda una capa impermeable, protección para el frío y una bolsa que proteja documentos y teléfono. Consulta qué equipamiento entrega el operador, cómo será el embarque y si hay restricciones de equipaje. Lleva medicamentos personales según indicación médica.'),
('Maleta de verano frente a invierno','En verano, prepara capas para mañanas frescas y viento aunque haya muchas horas de luz. En invierno añade abrigo térmico adecuado, guantes y calzado apto para superficies húmedas o con hielo. Comprueba las restricciones de equipaje de tu aerolínea.'),
('Lista final antes del vuelo','Documento de viaje, reservas descargadas, seguro, cargador compatible, tarjeta y respaldo, prendas por capas y calzado apropiado. Revisa el pronóstico del destino y de las excursiones, no solo la temperatura de tu ciudad de origen.')],
'Yo llevaría menos prendas, pero que combinen bien entre sí. La capa que corta el viento puede hacer más diferencia que otro pantalón.',sources=('chile',),group='Conectado y preparado')

add('guia','guardar-equipaje','Dónde guardar equipaje','Guardar las maletas puede liberar tu última mañana o facilitar una escala. Antes de dejarlas, confirma un servicio real, su horario y cómo vas a recuperarlas.',[
('Primera opción: tu alojamiento','Pregunta si recibe maletas antes del check-in o después del check-out, si tiene costo y si el espacio está supervisado. Confirma hasta qué hora podrás retirarlas, especialmente si vuelves de una excursión.'),
('Entre transportes','No presupongas que el aeropuerto, la empresa de bus o el puerto tienen consigna disponible. Consulta directamente por el servicio y sus condiciones. No existe aquí una consigna recomendada sin verificar.'),
('Qué conservar contigo','Lleva documentos, dinero, medicamentos y objetos necesarios para el día. Solicita comprobante o identificación del equipaje y revisa exclusiones por objetos de valor.'),
('Planifica la recogida','Añade el tiempo de volver al punto de guarda antes de tu transporte. Una ubicación céntrica puede resultar poco práctica si debes regresar en sentido contrario con las maletas.'),
('Dónde buscar una consigna real','Consulta primero a tu alojamiento y después a operadores de guarda equipaje con ubicación y horario verificables. Comprueba dirección exacta, reserva, identificación requerida y si reciben maletas de tu tamaño. No anunciaremos un comercio específico sin confirmación.'),
('Cruceros y escalas','Si bajas de un crucero, confirma horario de desembarco, hora límite de retorno y si puedes dejar equipaje fuera de la terminal. Prioriza opciones cercanas al recorrido y conserva siempre los documentos necesarios para volver a embarcar.'),
('Seguridad, responsabilidad y comprobantes','Pregunta por supervisión, seguro o límite de responsabilidad, objetos prohibidos, cargos adicionales y políticas ante un retiro tardío. Fotografía tu equipaje y conserva el recibo; no dejes pasaportes, medicamentos ni dinero.'),
('Ejemplo de último día sin cargar maletas','Si tu alojamiento ofrece custodia, deja allí el equipaje, pasea por un sector cercano y vuelve con tiempo suficiente para el aeropuerto o terminal. Suma transporte, retiro y margen por clima; una excursión larga puede no encajar con este plan.'),
('Si no encuentras consigna disponible','Pregunta al hospedaje por una salida tardía o coordinación con recepción, considera cambiar el orden de visitas o utiliza transporte que admita el equipaje. Mejor ajustar el plan que asumir que siempre existe una custodia abierta.')],
'Yo preguntaría por el retiro antes de entregar la maleta. El mejor servicio es el que encaja con tu recorrido y tu horario.',sources=(),group='Llegar y moverse')

add('transportes','micros','Micros · transporte urbano','Las micros permiten moverse por la ciudad con un presupuesto contenido. Para usarlas bien necesitas comprobar recorrido, sentido y paradero de regreso.',[
('Cómo preparar el viaje','Busca el recorrido vigente de Red Punta Arenas para la dirección de destino, no solo para el nombre del barrio. Las modificaciones de líneas pueden volver inútil una captura antigua. Pregunta en el alojamiento cuál es el paradero conveniente para tu salida.'),
('Antes de subir','Confirma con el conductor que el servicio pasa por tu punto de llegada y consulta la forma de pago aceptada. Lleva un medio de respaldo. Las tarifas reducidas tienen condiciones propias y no deben asumirse disponibles para cualquier visitante.'),
('Cuándo elegir otra opción','Con mucho equipaje, una conexión ajustada o un regreso de madrugada, compara una alternativa directa. Una línea urbana no debe confundirse con un traslado al aeropuerto ni con transporte a un parque.')],
'Yo miraría también el último regreso antes de salir. El trayecto de ida puede funcionar muy bien y la vuelta tener otra frecuencia.',sources=('red',),group='Dentro de la ciudad')
add('transportes','taxis','Taxis en Punta Arenas','El taxi puede simplificar llegadas con maletas, salidas tempranas y trayectos que requieren ir directamente a una dirección.',[
('Coordinar un servicio','Indica origen, destino, pasajeros y equipaje. Pregunta cómo se calcula la tarifa y si existe un valor acordado para ese servicio. En traslados largos conviene tener confirmación escrita del total y las condiciones.'),
('Aeropuerto y horarios especiales','Consulta los servicios oficiales del terminal y reserva si tu llegada necesita coordinación. Confirma si esperan un retraso del vuelo y cómo reconocerás al conductor. No extrapoles una tarifa urbana al aeropuerto.'),
('Excursiones y regreso','Si contratas un traslado a una zona natural, aclara si incluye espera o solo ida. Verifica comunicación y punto de recogida. No cuentes con que encontrarás un taxi circulando al terminar un sendero.')],
'Para un traslado temprano, yo confirmaría nuevamente la tarde anterior y dejaría el equipaje preparado.',sources=('puq-servicios',),group='Dentro de la ciudad')
add('transportes','colectivos','Colectivos · cómo funcionan','El colectivo es un transporte compartido con recorrido definido. Es útil si su ruta coincide con tu destino, pero funciona de forma distinta a un taxi particular.',[
('La diferencia principal','Otros pasajeros pueden subir y bajar durante el trayecto y el conductor sigue la ruta del servicio. Antes de subir, confirma la dirección y dónde te dejará. El número de línea sin el sentido puede no bastar.'),
('Precio y equipaje','Consulta la tarifa vigente y lleva cambio si corresponde. Si viajas con maletas grandes, niños que requieren silla o necesidades de acceso específicas, comprueba que el vehículo sea adecuado antes de elegirlo.'),
('Aprender una ruta útil','Pide al alojamiento que te indique un recorrido concreto y el punto de regreso. Para una primera visita es más fácil aprender una ruta práctica que intentar memorizar toda la red.')],
'Yo preguntaría “¿pasa por esta dirección?” y mostraría el lugar en el mapa. Una pregunta precisa evita dar una vuelta innecesaria.',sources=(),group='Dentro de la ciudad')
add('transportes','uber','Uber y aplicaciones','Uber publica cobertura para Punta Arenas. La disponibilidad, tiempo de espera y precio se comprueban dentro de la aplicación al momento de solicitar el viaje.',[
('Pedir un viaje','Escribe la dirección exacta y comprueba que el punto de recogida esté en el lado correcto de la calle. Si estás en el aeropuerto o puerto, consulta las condiciones del lugar para encontrarte con el vehículo.'),
('Antes de subir','Compara matrícula, modelo y conductor con la información de la aplicación. Revisa el destino y comparte el recorrido si te resulta útil. Mantén la coordinación dentro de los canales de la plataforma.'),
('No depender de disponibilidad remota','Poder pedir un vehículo en el centro no garantiza encontrarlo en una reserva o camino rural. Para esos destinos, organiza el regreso con anticipación. Si hay alta demanda, considera más margen para llegar a una conexión.')],
'Yo pediría el viaje desde un lugar protegido del viento y saldría cuando el vehículo esté próximo.',sources=('uber',),group='Dentro de la ciudad')
add('transportes','barcazas','Barcazas y cruces a Tierra del Fuego','Cruzar el Estrecho de Magallanes es parte de la experiencia, pero hay dos rutas que no debes confundir: Punta Arenas–Porvenir y Primera Angostura.',[
('Punta Arenas–Porvenir','TABSA conecta Tres Puentes con Bahía Chilota. El operador informa un viaje aproximado de dos horas, sujeto a condiciones. Revisa itinerario y reserva para pasajeros y vehículo según corresponda.'),
('Primera Angostura','Une Punta Delgada y Bahía Azul. Es un cruce distinto y exige recorrer por tierra hasta el embarque. Evalúa el circuito completo: llegar al otro lado no significa estar ya en Porvenir o en la Reserva Pingüino Rey.'),
('Con auto o excursión','Comprueba documentación, horario de presentación y política ante suspensión. Si visitas una reserva con cupo, coordina esa hora con el cruce y los kilómetros de carretera. Deja margen y consulta estado operativo el mismo día.')],
'Yo dibujaría el circuito completo antes de reservar. Barcaza, carretera y visita deben encajar como un solo viaje.',image='ferry',sources=('barcaza','angostura'),group='Fuera de la ciudad',place='Terminal Tres Puentes Punta Arenas')

add('compras','centro','Compras en el centro de Punta Arenas','El centro permite combinar comercio, una comida y un paseo patrimonial sin dedicar la jornada entera a traslados.',[
('Una ruta caminable','Utiliza la Plaza Muñoz Gamero como referencia y recorre las calles comerciales cercanas. Organiza una pausa interior si hace frío y evita acumular bolsas antes de subir al mirador o hacer una caminata larga.'),
('Qué comparar','Para recuerdos, artesanía y productos regionales, pregunta por origen y materiales. En ropa o equipamiento de viaje, compara calidad y uso real, además del precio. Guarda comprobantes para cambios.'),
('Si luego cruzas la frontera','Antes de comprar alimentos, productos animales o vegetales, revisa las restricciones del país al que viajarás. Que se venda legalmente en una tienda no significa que pueda cruzar cualquier control.')],
'Yo dejaría las compras voluminosas para el final del paseo y aprovecharía el centro para comparar con calma.',sources=('chile',),place='Plaza Muñoz Gamero Punta Arenas')
add('compras','zona-franca','Zona Franca · Zonaustral','Zona Franca es uno de los polos comerciales más conocidos de Punta Arenas. Conviene ir con una idea de lo que buscas y tiempo para comparar.',[
('Cómo organizar la visita','Está en el sector norte y requiere planificar el traslado desde el centro. Revisa el directorio y horario vigente del recinto; cada tienda o actividad puede manejar condiciones diferentes.'),
('Comprar con criterio','Compara el precio final, garantía y compatibilidad de los productos, especialmente electrónica. Para artículos grandes, considera el transporte, equipaje de tu compañía y posibles cargos o trámites posteriores.'),
('Una pausa bajo techo','Puede combinarse con servicios, comida y actividades del recinto según su programación. Si llueve, es una alternativa urbana, pero no toda la experiencia es necesariamente interior: comprueba distancias entre sectores.')],
'Yo llevaría una lista y precios de referencia. Una compra conveniente es la que realmente necesitas y puedes llevar de regreso.',sources=('zona',),place='Zonaustral Punta Arenas')
add('compras','espacio-urbano','Mall Espacio Urbano Pionero','Espacio Urbano Pionero suma comercio y servicios en un recorrido urbano diferente al centro histórico y a Zona Franca.',[
('Ubicación y traslado','El centro comercial figura en Avenida Eduardo Frei Montalva 01110. Verifica el acceso y la opción de transporte que te convenga desde tu alojamiento; no lo confundas con Zona Franca.'),
('Qué resolver en una visita','Organiza compras y una pausa para comer revisando el directorio vigente. Las tiendas, servicios y panoramas familiares pueden cambiar, por lo que conviene consultar la programación del propio mall.'),
('Si viajas en familia','Un espacio interior puede ayudar a equilibrar una jornada de viento o lluvia. Comprueba baños, accesos y condiciones de actividades infantiles antes de prometer una experiencia específica a los niños.')],
'Yo lo usaría como una parada práctica dentro del día, dejando tiempo para conocer también el comercio y la vida del centro.',sources=('mall',),place='Espacio Urbano Pionero Punta Arenas')

add('eventos','carnaval-de-invierno','Carnaval de Invierno','El Carnaval de Invierno forma parte de la identidad festiva de Punta Arenas: comparsas, carros y vida en la calle en plena temporada fría.',[
('Qué experiencia esperar','El atractivo está en ver cómo la ciudad celebra el invierno en comunidad. El recorrido, participantes y actividades complementarias se definen en cada programa municipal.'),
('Fechas con contexto','La edición 2026 se anunció para el 4 y 5 de julio. Es una referencia histórica, no un calendario para futuras temporadas. Para viajar especialmente por el carnaval, espera la confirmación de la edición que visitarás.'),
('Cómo prepararte','Lleva abrigo por capas, guantes y calzado de buen agarre. Acuerda un punto de encuentro si van en grupo, considera cortes de calles y organiza el regreso antes de que termine el espectáculo.')],
'Yo llegaría con tiempo y elegiría un lugar desde el que pueda salir con facilidad si voy con niños o alguien que necesita descansar.',sources=('invernadas','fundacion'),group='Invierno')
add('eventos','chapuzon','Chapuzón del Estrecho','El Chapuzón es una celebración organizada en las aguas del Estrecho de Magallanes. Puede vivirse como participante inscrito o como espectador.',[
('Participar requiere preparación','Revisa las bases de la edición, inscripción, requisitos de salud, edades y medidas de seguridad. No debe improvisarse como un baño individual fuera de la actividad organizada.'),
('Fecha de referencia','El programa de Invernadas 2026 fijó el Chapuzón para el 27 de junio. Las siguientes ediciones necesitan confirmación propia del municipio; no reutilices automáticamente ese día.'),
('Si vas a mirar','Lleva abrigo para permanecer en la costanera, mantén libres los accesos del operativo y respeta las áreas del público. Para los participantes, prepara ropa seca y sigue las instrucciones oficiales de principio a fin.')],
'Yo iría a disfrutar la energía del evento. Entrar al agua solo tiene sentido siguiendo las bases y las indicaciones del operativo.',sources=('invernadas','municipio'),group='Invierno')
add('eventos','festival-folclorico','Festival Folclórico en la Patagonia','El festival permite acercarse a la música, las tradiciones y las expresiones culturales que forman parte de la vida austral.',[
('Más allá del espectáculo','Es una oportunidad para escuchar repertorios regionales y conocer cómo se representa musicalmente la Patagonia. Conviene revisar la programación completa, porque puede incluir competencias y presentaciones distintas.'),
('Entradas y programación','La Fundación Cultural y el municipio publican las condiciones de cada edición. Consulta fechas, sede, horarios y mecanismo de acceso antes de organizar el viaje alrededor del evento.'),
('Combinar la jornada','Deja un paseo urbano o museo para el día y llega con tiempo al recinto. Si el espectáculo termina tarde, organiza el retorno y una opción de comida que funcione en ese horario.')],
'Yo revisaría quién se presenta cada jornada y elegiría por lo que me interesa escuchar, no solo por conseguir cualquier entrada.',sources=('fundacion',),group='Cultura y tradiciones')
add('eventos','ano-nuevo','Año Nuevo en Punta Arenas','El fin de año se disfruta mejor con una cena y un regreso organizados. Las celebraciones públicas dependen de los anuncios de cada temporada.',[
('Cena y reserva','Consulta con tiempo menús, horario, anticipo, cancelación y si la celebración continúa después de medianoche. Una reserva para cenar no siempre incluye fiesta o transporte.'),
('No dar por hecho un espectáculo','No se anuncia aquí un show de fuegos artificiales sin programa confirmado. Revisa los canales del municipio para saber si habrá actividades públicas y en qué lugar.'),
('Regreso y día siguiente','Acuerda el traslado y confirma la recepción de tu alojamiento. Si el 1 de enero tienes un bus, vuelo o excursión, revisa horarios y servicios de comida: puede haber operación especial por el feriado.')],
'Yo preferiría una celebración cercana al alojamiento o con traslado resuelto. Así empiezas el año disfrutando y no buscando cómo volver.',sources=('municipio',),group='Celebraciones')
add('eventos','fiestas-patrias','Fiestas Patrias en Magallanes','Septiembre combina tradiciones chilenas con el carácter propio de la región. La comida, la música y las actividades comunitarias pueden ser parte de tu visita.',[
('Qué buscar en el programa','Revisa fondas, actividades culturales y encuentros anunciados por el municipio. Comprueba lugar, horarios, accesos y si requieren entrada: no todos los años se repite la misma organización.'),
('Comer y compartir','Prueba preparaciones tradicionales según la oferta del lugar, consulta por porciones y pide alternativas para necesidades alimentarias. Planifica el regreso y evita conducir si consumes alcohol.'),
('Viajar en feriados','Reserva alojamiento y transportes necesarios, y verifica el funcionamiento de comercios y servicios. Si vas a cruzar a Argentina, consulta horarios de frontera y no te guíes por los de una semana normal.')],
'Yo dejaría espacio para disfrutar el ambiente local sin llenar el día de excursiones. Las celebraciones también son una forma de conocer la ciudad.',sources=('municipio',),group='Celebraciones')

add('vida-nocturna','bar-bulnes','Bar Bulnes','Una opción para combinar cerveza, comida y conversación. El local de Punta Arenas publica su ubicación y propuesta gastronómica en su propio sitio.',[
('Qué encontrarás','Su presentación destaca cervezas artesanales, pizzas y hamburguesas. Es una alternativa para una salida en la que la comida forma parte del plan, además de la bebida.'),
('Organiza la visita','El sitio identifica el local de Punta Arenas en Avenida Presidente Manuel Bulnes 0408. Consulta carta, horario y reservas directamente antes de ir, especialmente en fines de semana o feriados.'),
('Con qué combinarlo','Puedes organizar una jornada por el sector norte y terminar con una comida, dejando el regreso definido. No confundas la dirección de este local con otras sedes de la marca.')],
'Yo revisaría la carta antes y reservaría si voy en grupo. Para una noche tranquila, prefiero saber dónde sentarme y cómo volver.',sources=('bulnes',),place='Bar Bulnes Punta Arenas')
add('vida-nocturna','coyote','Coyote Restobar','Coyote aparece en la oferta nocturna de Punta Arenas con eventos y presentaciones. Antes de elegir la noche, revisa qué actividad está anunciada.',[
('La experiencia cambia por evento','Un tributo musical, una fiesta y una noche de restobar pueden tener accesos y horarios diferentes. Confirma qué se está vendiendo y qué incluye la entrada.'),
('Antes de pagar','Verifica que la publicación corresponda al local de Punta Arenas y a la fecha correcta. Consulta dirección, edad de ingreso, reserva de mesa y condiciones de cancelación con el organizador.'),
('Regreso sin improvisación','Deja una alternativa de transporte y evita programar una excursión muy temprana después de una salida larga. Si vas con otras personas, acuerden un punto de encuentro y una hora de regreso.')],
'Yo elegiría la noche por su programación y confirmaría si la entrada incluye mesa o solamente acceso.',sources=(),status='Consultar programación vigente')
add('vida-nocturna','el-trebol','El Trébol','El Trébol queda incorporado como referencia local propuesta por Ernesto. Su operación actual todavía necesita comprobación antes de recomendar una visita.',[
('Qué falta confirmar','Es necesario identificar el canal oficial del establecimiento y verificar ubicación, horario, tipo de ambiente y programación vigente. No se publica una dirección o precio sin una comprobación suficiente.'),
('Cómo organizar una noche mientras tanto','Para una salida inmediata, utiliza las fichas de locales que cuentan con canal propio y consulta su cartelera. Los directorios nocturnos pueden conservar nombres de negocios que cambiaron o dejaron de funcionar.')],
'Antes de enviarte a un local, yo prefiero confirmar que sigue funcionando y que ofrece el ambiente que estás buscando.',sources=(),status='Referencia local · operación por verificar')
add('vida-nocturna','kamikaze','Kamikaze','Kamikaze forma parte de las referencias de la bohemia magallánica. Las menciones históricas encontradas no bastan para asegurar su funcionamiento actual.',[
('Historia y actualidad son distintas','Un local puede ser muy recordado y, sin embargo, haber cambiado de nombre, dirección o actividad. Esta ficha conserva el nombre solicitado sin presentarlo como una discoteca confirmada para esta temporada.'),
('Antes de organizar la salida','Se necesita una cartelera reciente o un canal oficial verificable para publicar horarios, entradas y ubicación. Para salir hoy, comprueba la programación de los locales con información vigente.')],
'Yo no usaría una reseña antigua para decidir adónde ir esta noche. La cartelera reciente es lo que permite armar un buen plan.',sources=(),status='Referencia histórica · operación por verificar')
add('vida-nocturna','muchacha','Muchacha Restobar','Muchacha publica una propuesta que combina comida, coctelería y programación musical. La experiencia depende de la noche y del evento elegido.',[
('Revisar la cartelera','Su sitio anuncia actividades como DJs, karaoke y fiestas con distintos estilos. Mira qué propuesta corresponde a tu fecha y consulta las condiciones de ingreso.'),
('Ubicación y reserva','El canal oficial identifica Bulnes 0574. Confirma horario, disponibilidad de mesa y si corresponde comprar una entrada aparte. No confundas una reserva de comida con acceso a cualquier evento.'),
('Cómo cerrar el plan','Organiza el retorno y conserva la dirección de tu alojamiento. Si compartes una mesa o vas a un evento concurrido, acuerda cómo se encontrarán al salir.')],
'Yo escogería la noche según la música que quiero escuchar. Un mismo local puede sentirse muy distinto de una fecha a otra.',sources=('muchacha',),place='Muchacha Restobar Punta Arenas')

# Gastronomía: las descripciones separan la identidad del local de la carta y tarifa variables.
add('gastronomia','dona-ines','Doña Inés','Doña Inés es la propuesta gastronómica publicada por Dreams Punta Arenas, con una experiencia de buffet y vista panorámica.',[
('Qué tipo de comida esperar','Dreams presenta una variedad de carnes, pastas, pescados y mariscos. La oferta concreta debe consultarse para el día de la visita; no se promete que un producto esté siempre incluido.'),
('Antes de reservar','Pregunta horario, modalidad de servicio, valor por persona, bebidas y condiciones para niños. Si tienes alergias o restricciones alimentarias, consulta directamente cómo las atienden.'),
('Un plan para ir con calma','Puede ser una opción para una comida prolongada o una ocasión especial. Si tienes una excursión después, deja margen para disfrutar sin correr y confirma la distancia al punto de encuentro.')],
'Yo confirmaría qué incluye el precio antes de reservar y pediría una mesa adecuada al grupo.',sources=('ines',),place='Dreams Punta Arenas')
for slug,title,intro,a,b,c,src in [
('sotitos',"Sotito’s",'Una referencia de la cocina de Punta Arenas para quienes buscan una comida de restaurante y sabores vinculados al mar y a la región.',
 'Su presencia en los directorios gastronómicos lo convierte en un nombre a considerar al comparar restaurantes. Revisa la carta vigente: pescados, mariscos y preparaciones regionales dependen de la oferta del día.',
 'Confirma reserva, dirección y horario por el canal del establecimiento. Para centolla u otros productos de valor variable, pregunta por preparación, porción y precio antes de pedir.',
 'Puedes reservarlo como la comida principal de un día urbano. Evita una conexión ajustada inmediatamente después y consulta opciones para quienes no comen productos del mar.',('restaurantes',)),
('savoy','Savoy','Savoy es otro de los nombres tradicionales que aparecen en los directorios gastronómicos de Punta Arenas.',
 'La referencia permite incluirlo en una ruta de restaurantes del centro. Antes de elegir, consulta la carta actual y el tipo de servicio que ofrece para el horario que buscas.',
 'El directorio turístico sitúa Savoy en José Menéndez 1073. Verifica la información con el local, especialmente en feriados. Si vas en grupo, pregunta por reserva y tiempos de atención.',
 'Organiza la visita junto a un recorrido por el centro y patrimonio exterior. Una comida sin prisa puede ser una buena pausa entre la plaza y una caminata posterior.',('restaurantes',)),
('lomitos',"Lomito’s",'Los sándwiches chilenos también son parte del viaje. Lomito’s aparece como una alternativa para ese momento más informal.',
 'Un lomito, un churrasco y un completo son preparaciones diferentes. Mira los ingredientes de la carta para elegir y pregunta por el tamaño si no conoces las porciones.',
 'Confirma horario y dirección del local antes de ir. Si tienes una restricción alimentaria, pregunta por panes, salsas y preparación: quitar un ingrediente no siempre evita contaminación cruzada.',
 'Es un tipo de parada que puedes incorporar entre paseos urbanos, sin necesidad de convertir cada comida en una reserva extensa. Aun así, deja tiempo si visitas en una hora concurrida.',()),
('dinos-pizza',"Dino’s Pizza",'Dino’s Pizza forma parte de los nombres que los visitantes encuentran al buscar pizzas y comida informal en Punta Arenas.',
 'Consulta la carta para distinguir pizzas, sándwiches y otras preparaciones disponibles. La descripción del nombre no garantiza que toda la oferta se limite a pizzas.',
 'Revisa tamaño, ingredientes y precio vigente antes de pedir. Si vas a retirar o pedir delivery, confirma cobertura, tiempo estimado y dirección exacta de entrega.',
 'Puede encajar en una jornada familiar o una cena sencilla después de un paseo. Si vienes de una excursión, comprueba el horario de cocina y no solo el de apertura del local.',()),
('cuatro-estaciones','Cuatro Estaciones','Una alternativa de pizzería para una comida compartida o un plan informal en la ciudad.',
 'Compara tamaños e ingredientes y pregunta cuántas personas suelen compartir cada formato. Para un grupo con preferencias distintas, revisa si es posible dividir sabores y qué costo tiene.',
 'Los directorios sitúan la pizzería en Bories 498. Confirma el dato y el horario con el establecimiento antes de desplazarte. Consulta por reserva, retiro o entrega según tu plan.',
 'Organiza una comida flexible dentro de un recorrido urbano. Si hace frío y quieres quedarte, pregunta por disponibilidad de mesas antes de llegar con un grupo grande.',()),
]:
 add('gastronomia',slug,title,intro,[('La propuesta',a),('Antes de ir',b),('Cómo incluirlo en tu día',c)],'Yo revisaría la carta y el precio vigente antes de elegir. Lo importante es encontrar el lugar que encaja con tu momento y tu presupuesto.',sources=src)
add('gastronomia','sabores-magallanicos','Qué comer en Magallanes','La gastronomía también cuenta la relación de la región con el mar, las estancias y sus productos. Conviene explorar estilos distintos en vez de repetir la misma comida cada día.',[
('Mar y cocina regional','Consulta por pescados y mariscos disponibles, su preparación y procedencia. Si buscas centolla, confirma qué plato estás pidiendo y si el precio corresponde a una porción, preparación o producto completo.'),
('Comida de estancia','El cordero aparece entre los sabores asociados a la Patagonia. Pregunta por técnica de cocción, guarniciones y tamaño de la porción. Una experiencia de estancia necesita revisar traslado y duración completa.'),
('Pausas cotidianas','Deja espacio para sándwiches, cafeterías y una comida sencilla entre paseos. Si quieres probar productos con calafate, consulta ingredientes y restricciones para llevarlos a otro país.')],
'Yo alternaría una comida especial con paradas cotidianas. Conocer una ciudad también pasa por sentarse donde cabe una conversación sin apuro.',sources=('chile',))

add('cultura','museos','Museos de Punta Arenas','Los museos permiten comprender la región más allá de una fotografía del paisaje. Elige según tus intereses y confirma apertura antes de armar la jornada.',[
('Maggiorino Borgatello','Su colección aborda patrimonio natural, historia y pueblos del territorio austral. El museo publica su ubicación en Avenida Bulnes 336 y permite planificar la visita en su canal oficial.'),
('Museo Regional de Magallanes','Su sitio informa cierre temporal asociado a conservación y restauración. El edificio puede formar parte de un recorrido exterior, pero no se presenta como una visita interior disponible. Revisa su oferta digital y cualquier anuncio de reapertura.'),
('Museo del Recuerdo y Nao Victoria','El primero forma parte de la red de museos de la región; el segundo se relaciona con la navegación histórica y las réplicas de embarcaciones. Organiza cada acceso por separado y comprueba su operación antes de ir.')],
'Yo escogería uno o dos museos que me interesen y les daría tiempo. Entrar solo para completar una lista suele dejar menos recuerdos.',sources=('borgatello','museo','museos'),group='Patrimonio')
add('cultura','maggiorino-borgatello','Museo Maggiorino Borgatello','Un lugar para acercarse al patrimonio natural y cultural de Magallanes, con colecciones que invitan a mirar el territorio con más contexto.',[
('Qué aporta a la visita','El museo presenta temas de historia, arqueología, paleontología, fauna y pueblos originarios. Recorre sus colecciones considerando también el contexto de formación de los museos y las miradas actuales sobre el patrimonio.'),
('Planificar el acceso','Su dirección publicada es Avenida Bulnes 336, junto al Santuario María Auxiliadora. Consulta horario, entradas y condiciones de visita en el canal del museo.'),
('Cómo combinarlo','Puede integrarse a una jornada por el eje Bulnes, dejando espacio para comer y para una visita respetuosa al Cementerio Sara Braun. Comprueba distancias y accesibilidad según tu grupo.')],
'Yo visitaría el museo antes de una excursión de naturaleza: después puedes reconocer el paisaje con otros ojos.',sources=('borgatello',),place='Museo Maggiorino Borgatello Punta Arenas',group='Museos')
add('cultura','museo-regional','Museo Regional de Magallanes','El Palacio Braun Menéndez es parte del patrimonio urbano de la ciudad. La visita interior necesita considerar el cierre temporal que comunica el museo.',[
('Estado de visita','El canal oficial informa suspensión de atención al público por trabajos y preparación de restauración. Esta guía no publica horarios antiguos como si siguieran operativos. Revisa los avisos del museo para cualquier cambio.'),
('Leer el edificio','Su arquitectura permite acercarse a una etapa de riqueza urbana vinculada a la ganadería y las redes comerciales. Esa historia debe leerse junto a los impactos que la colonización tuvo en los pueblos originarios.'),
('Alternativas','Puedes observar el exterior desde el espacio público y consultar los recursos digitales del museo. Para una actividad interior, revisa la ficha de Maggiorino Borgatello u otro espacio con apertura confirmada.')],
'Yo mantendría el palacio en el paseo patrimonial, pero elegiría otro museo para la visita interior mientras dure el cierre.',sources=('museo',),place='Museo Regional de Magallanes Punta Arenas',group='Museos',status='Cierre temporal anunciado por el museo')
add('cultura','museo-del-recuerdo','Museo del Recuerdo','Una referencia para acercarse a la vida material, los oficios y las formas de habitar la región.',[
('Por qué incluirlo','Forma parte de la red museal de Magallanes y se vincula al Instituto de la Patagonia de la Universidad de Magallanes. Es una opción para quienes quieren explorar la historia cotidiana además de los grandes monumentos.'),
('Preparar la visita','Consulta directamente el horario vigente, acceso, entradas y disponibilidad de recorrido. Un museo con espacios exteriores requiere preparar abrigo y calzado, aunque el día comience despejado.'),
('Combinar por sector','Organiza su visita junto a actividades del área norte si el acceso está confirmado. Evita cruzar la ciudad varias veces por intentar encajar demasiadas paradas.')],
'Yo preguntaría si hay un recorrido guiado: las historias de los objetos ayudan mucho más que una visita apresurada.',sources=('recuerdo','museos'),place='Museo del Recuerdo Punta Arenas',group='Museos')
add('cultura','iglesias','Iglesias y patrimonio religioso','Las iglesias forman parte del paisaje urbano y de la historia de las comunidades de Punta Arenas. Algunas se pueden combinar con museos y un paseo por el centro.',[
('Catedral y centro histórico','La Catedral se relaciona con el conjunto de edificios que rodean la Plaza Muñoz Gamero. Observa su posición dentro del centro cívico y respeta celebraciones y horarios religiosos.'),
('Santuario María Auxiliadora','Su cercanía al Museo Maggiorino Borgatello permite organizar un recorrido por el eje Bulnes. La visita turística debe ajustarse al funcionamiento del templo y no interrumpir sus actividades.'),
('Una visita respetuosa','No asumas que el acceso interior está siempre permitido. Consulta antes de fotografiar personas, usar flash o recorrer durante un oficio. La guía incluye patrimonio; no convierte los lugares de culto en un escenario privado.')],
'Yo entraría con calma y, si hay una celebración, volvería en otro momento para recorrer el interior.',sources=('plaza','borgatello'),group='Patrimonio')
add('cultura','centros-culturales','Centros culturales y programación','Para conocer la ciudad viva, revisa sus exposiciones, talleres y escenarios. La programación cambia y puede aportar un plan que no figura en los recorridos clásicos.',[
('Buscar por fecha','Consulta el municipio y la Fundación Cultural para exposiciones y actividades de la semana de tu visita. Distingue una sede permanente de un evento temporal.'),
('Sala Zonaustral','El recinto comercial publica una sala para actividades culturales, comunitarias y de emprendimiento. Comprueba la cartelera y acceso de cada evento antes de trasladarte.'),
('Cómo incluir una actividad','Una exposición puede complementar una mañana de compras; un concierto pide reservar una parte mayor de la jornada. Revisa duración, entradas y accesibilidad para que el plan encaje con tu grupo.')],
'Yo miraría la agenda unos días antes de llegar. A veces una actividad local termina siendo el mejor recuerdo del viaje.',sources=('fundacion','zona'),group='Ciudad cultural')
add('cultura','bibliotecas','Bibliotecas y memoria escrita','Los libros, archivos y bibliotecas permiten acercarse a las voces de Magallanes. Son una forma de conocer historias que no siempre se ven caminando por la plaza.',[
('Qué buscar','Pregunta por autores regionales, historia local y material sobre pueblos originarios. Distingue una colección de consulta de una exposición abierta a visitantes.'),
('Consultar antes','Verifica horarios, requisitos de acceso y si es necesario pedir una visita o un documento con anticipación. Un archivo especializado no funciona como una biblioteca de libre recorrido.'),
('Una pausa distinta','Puedes sumar lectura y consulta a un día de patrimonio o clima difícil. Respeta el silencio, las normas de fotografía y el cuidado de los documentos.')],
'Yo buscaría una lectura breve sobre el lugar antes de recorrerlo. Una historia cambia la manera de mirar una calle.',sources=('fundacion','municipio'),group='Ciudad cultural')

add('naturaleza','reserva-magallanes','Reserva Nacional Magallanes','Bosque y senderos cerca de la ciudad para cambiar de escala: del centro urbano a los paisajes de la península de Brunswick.',[
('Elegir un recorrido','CONAF describe distintos senderos y ambientes de bosque magallánico. Elige el recorrido según experiencia, tiempo disponible y estado actual, no solo por la distancia en el mapa.'),
('Acceso y retorno','Confirma apertura, entrada y condiciones del camino antes de salir. Organiza cómo volverás al terminar; no presupongas que tendrás cobertura o un vehículo disponible en la puerta.'),
('Caminar con cuidado','Lleva abrigo, agua, calzado apropiado y orientación sin conexión. Respeta señalización y límites de acceso. Si buscas un recorrido accesible, consulta la condición vigente del sendero informado para movilidad reducida.')],
'Yo saldría temprano y elegiría un recorrido que me permita volver con margen. El bosque merece tiempo y atención.',sources=('reserva',),place='Reserva Nacional Magallanes',group='Bosques y senderos')
add('naturaleza','isla-magdalena','Isla Magdalena · pingüinos magallánicos','La navegación a Isla Magdalena permite acercarse al hábitat de pingüinos magallánicos dentro del Monumento Natural Los Pingüinos.',[
('Una experiencia estacional','La fauna y la operación tienen temporadas. Confirma apertura del área y salida con el operador antes de reservar. El estado del mar puede impedir un zarpe incluso con visita programada.'),
('Durante el recorrido','Camina por el sendero habilitado, deja pasar a las aves y sigue las indicaciones de guardaparques y guías. No toques, alimentes ni persigas animales para conseguir una fotografía.'),
('Qué llevar','Abrigo contra el viento, calzado apropiado y protección para la cámara. Revisa si el servicio incluye traslado terrestre y acceso al área; no todos los programas se venden con las mismas inclusiones.')],
'Yo dejaría una jornada flexible por si hay que reprogramar. La navegación depende del mar, y respetar esa decisión es parte de viajar aquí.',image='pinguinos',sources=('pinguinos',),group='Pingüineras y fauna')
add('naturaleza','pinguino-rey','Reserva Natural Pingüino Rey','La observación del pingüino rey en Bahía Inútil se realiza en Tierra del Fuego. Desde Punta Arenas requiere coordinar cruce, carretera y reserva de visita.',[
('No es Isla Magdalena','Son especies, destinos y logísticas distintas. Para Bahía Inútil se necesita resolver la visita a la reserva y los desplazamientos terrestres, además de la barcaza.'),
('Reserva y observación','Consulta cupos, temporada, horario y normas en el canal de la reserva. La observación se organiza para reducir molestias a la colonia, por lo que no debes esperar caminar libremente entre los animales.'),
('Un circuito de jornada larga','Compara tour y viaje por cuenta propia considerando horas completas y margen para el regreso. Si necesitas accesibilidad, consulta la silla adaptada y las condiciones concretas del recorrido antes de reservar.')],
'Yo coordinaría primero el cupo de visita y después el resto del circuito. Llegar hasta la reserva no garantiza entrar sin reserva.',image='pinguinos',sources=('rey','barcaza','angostura'),group='Pingüineras y fauna')
add('naturaleza','laguna-parrillar','Laguna Parrillar','Una opción para acercarse a ambientes naturales al sur de Punta Arenas, siempre con atención al acceso y a su operación estacional.',[
('Antes de salir','Consulta a la administración el estado de apertura y de los caminos. CONAF anunció el inicio de la temporada 2026–2027 para el 16 de octubre; revisa los avisos vigentes para el día que viajarás.'),
('Armar una jornada cómoda','Organiza transporte de ida y regreso, colación, abrigo y tiempo para recorrer sin prisa. No planifiques servicios de alimentación o abastecimiento sin confirmar que están disponibles.'),
('Cuidar el entorno','Sigue las normas del área para senderos y uso de espacios. Cualquier actividad como pesca tiene condiciones específicas; entrar a una reserva no significa tener autorización para realizarla.')],
'Yo llevaría lo necesario desde la ciudad y volvería con todos los residuos. Es un lugar para bajar el ritmo.',sources=('parrillar',),place='Reserva Nacional Laguna Parrillar',group='Bosques y senderos')
add('naturaleza','pali-aike','Parque Nacional Pali Aike','Pali Aike muestra otra cara de Magallanes: estepa y formas volcánicas, lejos de la imagen de bosque y costa de la ciudad.',[
('Qué lo distingue','CONAF destaca su geomorfología y ambientes esteparios. La cueva y el paisaje permiten acercarse también a la larga presencia humana en el territorio, sin intervenir ni retirar elementos del lugar.'),
('Preparar el trayecto','Es una salida fuera del área urbana. Confirma acceso, apertura y condición de caminos, organiza combustible y regreso. La distancia y el terreno hacen necesario planificar la jornada completa.'),
('Caminar en estepa','Lleva protección contra el viento, agua y calzado adecuado. No te acerques a fauna ni salgas de áreas habilitadas. El paisaje abierto no garantiza orientación fácil ni refugio próximo.')],
'Yo elegiría Pali Aike por sus paisajes distintos y le daría su propio día. No intentaría sumarlo como una parada rápida entre demasiados destinos.',sources=('pali',),place='Parque Nacional Pali Aike',group='Estepa y paisajes')
add('naturaleza','faro-san-isidro','Faro San Isidro','El faro combina historia marítima y costa al sur de la península de Brunswick. Llegar requiere distinguir el tramo en vehículo del recorrido a pie.',[
('Su historia en el estrecho','El Consejo de Monumentos sitúa su inauguración en 1904 y explica su función para la navegación hacia Punta Arenas. Su paisaje ayuda a entender la importancia de orientar embarcaciones en este paso.'),
('Cómo preparar el acceso','Consulta el estado de la ruta y del sendero, el punto exacto donde termina el acceso vehicular y las condiciones del día. No interpretes la ubicación del faro en el mapa como una carretera hasta su puerta.'),
('Tiempo y equipamiento','Lleva calzado para terreno costero, abrigo y provisiones, con retorno coordinado. El acceso al paisaje no garantiza que el interior del edificio esté abierto al público.')],
'Yo preguntaría cómo está el tramo a pie antes de salir y dejaría margen para volver con luz.',sources=('faro',),place='Faro San Isidro Magallanes',group='Costa y trekking')
add('naturaleza','trekking-y-senderos','Trekking y senderos · elige tu nivel','Una caminata urbana, un sendero de reserva y una travesía remota requieren preparación distinta. El mejor recorrido es el que coincide con tu experiencia y las condiciones del día.',[
('Para empezar','Una reserva con senderos señalizados puede ser una forma de acercarse al bosque, siempre que el acceso esté confirmado. Consulta distancia, desnivel y superficie, y elige una opción que deje energía para el regreso.'),
('Monte Tarn y rutas exigentes','La mención de un cerro en una guía no implica que sea una excursión sencilla. Antes de intentar una ruta de montaña, verifica navegación, terreno, pronóstico, equipo y necesidad de guía. No se publica aquí una ruta técnica sin levantamiento específico.'),
('Travesías hacia Cabo Froward','Deben tratarse como proyectos de expedición, con planificación de costas, cruces, comunicación y logística. No equivalen a una caminata espontánea de tarde desde Punta Arenas.'),
('Un criterio para decidir','Si el clima empeora, no encuentras el trazado o el grupo se está agotando, dar vuelta puede ser la mejor elección. Comparte el plan y no dependas solo de una aplicación para orientarte.')],
'Yo prefiero volver con ganas de otro sendero que terminar una ruta por obligación. El paisaje seguirá ahí para otra oportunidad.',sources=('reserva','chile'),group='Costa y trekking')

# Atracciones, tours y rutas urbanas.
add('atracciones','plaza-munoz-gamero','Plaza Muñoz Gamero','El punto de partida para reconocer el centro histórico: árboles, monumentos y edificios que ayudan a leer la historia urbana de Punta Arenas.',[
('Mirar el conjunto','El Consejo de Monumentos reconoce la plaza y los edificios que la rodean como una zona patrimonial. Recorre sus bordes y observa cómo el espacio público articula arquitectura cívica, religiosa y residencial.'),
('Un paseo con contexto','Además de fotografiar el monumento, pregunta qué historias representa y cuáles quedaron fuera de la imagen tradicional de la colonización. La memoria de la región incluye a sus pueblos originarios y a distintas comunidades migrantes.'),
('Cómo seguir el recorrido','Desde aquí organiza un paseo al centro comercial, una comida o la costanera. Para el Cerro de la Cruz considera la subida y las condiciones de la calle; no todas las extensiones tienen la misma dificultad.')],
'Yo empezaría aquí sin apuro, mirando hacia los edificios. La plaza funciona como una pequeña introducción a la ciudad.',image='plaza',sources=('plaza',),place='Plaza Muñoz Gamero Punta Arenas')
add('atracciones','cerro-de-la-cruz','Mirador Cerro de la Cruz','Una vista para relacionar las calles, las techumbres y el Estrecho de Magallanes. El mirador permite entender la ciudad desde otra perspectiva.',[
('Subir con tiempo','El acceso desde el centro incluye pendiente. Elige calzado cómodo y revisa la condición de las superficies, especialmente cuando hay hielo. Si necesitas evitar desniveles, consulta un traslado adecuado y el acceso final.'),
('Qué mirar','Dedica unos minutos a ubicar la costa y reconocer los sectores que recorrerás. La luz cambia el paisaje durante el día; no se necesita una puesta de sol para disfrutar la vista.'),
('Fotografía y viento','Asegura tus pertenencias y no te apoyes en lugares no habilitados para mejorar el encuadre. Después puedes bajar hacia una pausa para comer y continuar con un paseo urbano corto.')],
'Yo subiría cuando la visibilidad esté buena, aunque no sea la hora que tenía prevista. En Patagonia conviene aprovechar las ventanas del tiempo.',sources=('chile',),place='Mirador Cerro de la Cruz Punta Arenas')
add('atracciones','costanera','Costanera del Estrecho','Un paseo para mirar el movimiento del mar y sentir la escala del estrecho. La costanera se disfruta por tramos, sin obligación de recorrerla completa.',[
('Elegir un sector','Combina un tramo cercano al centro con una comida o descanso interior. Revisa el viento y adapta la distancia al grupo. Un recorrido lineal puede necesitar transporte de regreso.'),
('Observar sin apuro','Busca aves, embarcaciones y cambios de luz desde espacios habilitados. Lleva binoculares si te interesa observar fauna, sin acercarte ni interferir con ella.'),
('Con niños y bicicleta','Respeta las áreas compartidas y mantén atención a cruces y circulación. El espacio costero es público y los eventos pueden modificar accesos o concentrar gente en ciertos sectores.')],
'Yo haría la costanera cuando el tiempo acompañe y dejaría un café cerca como alternativa si se levanta el viento.',sources=('chile',),place='Costanera del Estrecho Punta Arenas')
add('atracciones','cementerio-sara-braun','Cementerio Municipal Sara Braun','Un lugar de memoria que permite reconocer historias personales y comunidades que formaron parte de Punta Arenas.',[
('Patrimonio y recogimiento','Sus avenidas arboladas, mausoleos y sepulturas forman parte de su interés patrimonial. También sigue siendo un cementerio: recorre con discreción y da prioridad a quienes visitan a sus familiares.'),
('Preparar la visita','El canal del recinto publica Avenida Bulnes 029 y las condiciones de visita. Consulta horario y acceso antes de ir; no utilices una tarifa o apertura antigua sin comprobar.'),
('Fotografiar con respeto','Evita fotografiar ceremonias o personas en duelo. Observa símbolos, idiomas y estilos para comprender la diversidad de historias, sin entrar en espacios restringidos.')],
'Yo lo recorrería en silencio y con tiempo para leer. El valor del lugar está en las historias, no solo en sus cipreses.',sources=('cementerio',),place='Cementerio Municipal Sara Braun Punta Arenas')
add('atracciones','nao-victoria','Museo Nao Victoria','Las réplicas de embarcaciones acercan la navegación histórica a una escala que se puede comprender con el cuerpo y la mirada.',[
('Qué propone','El museo de sitio se vincula a las exploraciones marítimas y figura entre las referencias de visita de Punta Arenas. Distingue una réplica contemporánea de un barco original conservado.'),
('Planificar el acceso','Comprueba horario, entrada, ubicación actual y condiciones del recorrido con el establecimiento. Considera traslado al sector norte y calzado para plataformas o escaleras si forman parte de la visita.'),
('Con niños o movilidad reducida','Pregunta por accesos a cada embarcación y sectores visitables. Las escaleras de un barco pueden impedir parte del recorrido a algunas personas; es mejor conocerlo antes de comprar.')],
'Yo lo combinaría con una jornada por el norte, en lugar de cruzar toda la ciudad solo para una parada apresurada.',sources=('museos','chile'),place='Museo Nao Victoria Punta Arenas')
add('atracciones','fuerte-bulnes','Fuerte Bulnes y Parque del Estrecho','Historia y paisaje se encuentran al sur de Punta Arenas. La visita permite recorrer un territorio con memorias anteriores y posteriores a los asentamientos históricos.',[
('Qué incluye el lugar','El Parque del Estrecho reúne recursos patrimoniales y naturales, entre ellos Fuerte Bulnes y el sitio de la Ciudad Rey Don Felipe, conocido como Puerto del Hambre. Consulta qué sectores incluye la entrada vigente.'),
('Un paseo más amplio','El parque publica senderos y miradores con vistas hacia distintos puntos del estrecho. No reduzcas la visita a una fotografía del fuerte: da espacio al paisaje y a la interpretación.'),
('Logística del día','Comprueba apertura, tiempo de recorrido, alimentación y traslado. Lleva abrigo y un regreso acordado. El parque y el Faro San Isidro no deben asumirse como una misma visita sin evaluar tiempos y accesos.')],
'Yo dejaría varias horas para recorrer y entender el lugar. La ruta del sur se disfruta más sin intentar verlo todo de una sola vez.',sources=('estrecho',),place='Parque del Estrecho Fuerte Bulnes')

for slug,title,intro,blocks,tip,img,refs in [
('city-tour','City tour de Punta Arenas','Una primera mirada para ubicarte en la ciudad y entender las historias detrás de sus principales lugares.',[
('Qué priorizar','Plaza Muñoz Gamero, costanera y un mirador permiten una introducción variada. El recorrido real depende del clima, de la movilidad del grupo y de las aperturas de cada lugar.'),('Antes de contratar','Pregunta duración, idiomas, vehículo, entradas y punto de encuentro. Una parada exterior y una visita de museo no son lo mismo. Confirma también si termina en tu alojamiento o en otro punto.'),
("Plaza Muñoz Gamero y patrimonio","El corazón de Punta Arenas reúne plazas, edificios cívicos y casonas que cuentan la historia de la ciudad portuaria. Comprueba si el guía realiza una caminata o únicamente una parada fotográfica."),
("Cerro de la Cruz y miradores","Desde el sector alto puedes observar la trama urbana, el Estrecho de Magallanes y en días despejados Tierra del Fuego. Revisa accesibilidad, pendiente y exposición al viento."),
("Costanera y Estrecho","La costanera, las letras de la ciudad y el borde marítimo son paradas panorámicas frecuentes. El itinerario concreto cambia según el operador."),
("Cementerio Sara Braun y museos","Algunas modalidades pasan por el cementerio o incluyen patrimonio interior. Las entradas y tiempos de visita no deben darse por incluidos sin confirmación."),
("Modalidades de recorrido","Existen opciones compartidas de aproximadamente tres horas y circuitos privados de duración variable. Pregunta recogida, idiomas, entradas y punto final."),
("Cruceristas y familias","Si llegas en crucero informa nombre del barco y hora límite de retorno; si viajas con niños o personas con movilidad reducida, confirma caminatas, escalones y baños.")],
'Yo usaría el primer recorrido para orientarme y volvería por mi cuenta al lugar que más me haya interesado.','ciudad',('chile','sernatur')),
('isla-magdalena','Navegación a Isla Magdalena','Una experiencia de fauna y navegación que debe organizarse con flexibilidad por las condiciones del estrecho.',[
('Qué comparar','Revisa embarcación, muelle de salida, traslado terrestre, entrada al área, tiempo de recorrido y política de cancelación. No compares únicamente el precio del anuncio.'),('Qué esperar','La presencia de fauna y la posibilidad de desembarco dependen de temporada y operación. En la isla sigue los senderos y las indicaciones, sin acercarte deliberadamente a los animales.'),
("Navegación por el estrecho","El recorrido suele combinar traslado a embarcadero y travesía marítima. La duración y el puerto concreto varían por operador."),
("Pingüinos magallánicos","En temporada de apertura, el Monumento Natural Los Pingüinos permite recorrer senderos señalizados y observar aves en su hábitat. No toques, alimentes ni persigas la fauna."),
("Isla Marta es otra modalidad","Algunos programas navegan frente a Isla Marta para observar lobos marinos, sin desembarco. Comprueba si tu reserva incluye esa extensión."),
("Apertura y seguridad","La disponibilidad depende de temporada, autoridad del área, clima y condiciones del mar. Un anuncio en internet no asegura salida o desembarco."),
("Qué llevar","Abrigo cortaviento e impermeable, calzado antideslizante y protección de cámara. Consulta condiciones para niños y personas con movilidad reducida."),
("Planifica la reserva","Reserva al principio de tu estancia para conservar margen de reprogramación. Confirma entradas, traslados, duración e idioma del guía.")],
'Yo reservaría esta actividad al principio de la estadía para conservar margen si se reprograma.','pinguinos',('pinguinos','sernatur')),
('tierra-del-fuego','Tierra del Fuego y pingüino rey','Un recorrido para cruzar el estrecho y conocer un territorio distinto, con largos tramos terrestres y reservas coordinadas.',[
('La jornada completa','Comprueba ruta de barcaza, horas de carretera, visita a la reserva, alimentación y regreso. La visita a Porvenir puede o no formar parte del programa; pide el itinerario concreto.'),('Qué confirmar','Revisa cupo del Pingüino Rey, restricciones de movilidad y política si se suspende un cruce. El tiempo de navegación no es la duración total de la excursión.'),
("Cruce del Estrecho de Magallanes","La salida puede utilizar distintas rutas marítimas y terrestres. Verifica compañía de ferry, horas de embarque y los tiempos de espera."),
("Carreteras de Tierra del Fuego","Paisajes de estepa, estancias y poblaciones como Porvenir o Cerro Sombrero pueden aparecer en distintos circuitos. No presupongas que todas las paradas están incluidas."),
("Reserva Natural Pingüino Rey","La visita de Bahía Inútil tiene horarios, cupos y normas de conservación específicas. Confirma ticket y acceso antes del viaje."),
("Otra especie y otra logística","Pingüino Rey no es Isla Magdalena: requiere un circuito terrestre extenso y cruces en ferry, con tiempo total de jornada muy distinto."),
("Un día largo","Pregunta por recogida temprana, comida, baños, entradas y hora estimada de regreso. Evita combinarlo con vuelos el mismo día."),
("Preparación","Lleva abrigo y agua; consulta restricciones para niños, accesibilidad del sendero y políticas de cancelación ante suspensión marítima.")],
'Yo elegiría el programa mirando el tiempo efectivo de visita y la comodidad del traslado, además del precio.','ferry',('rey','barcaza','angostura')),
('parque-del-estrecho','Historia al sur · Parque del Estrecho','Una salida para combinar el paisaje costero con Fuerte Bulnes y la interpretación histórica del territorio.',[
('Un programa con contexto','Consulta qué sectores y senderos están incluidos y si la visita tiene guía. Una explicación histórica ayuda a relacionar los lugares y a superar una mirada de simples paradas fotográficas.'),('Antes de salir','Pregunta por tiempo total, entradas, comida, vestimenta y punto de recogida. Si quieres añadir otra caminata, revisa primero su viabilidad y dificultad.'),
("Paisaje rumbo al sur","La costa austral acompaña la ruta hacia el Parque del Estrecho. El viento y el estado de accesos pueden modificar las paradas panorámicas."),
("Historia de Fuerte Bulnes","El sitio recuerda el asentamiento chileno de 1843. La reconstrucción permite comprender la vida de los primeros ocupantes y la importancia estratégica del estrecho."),
("Puerto del Hambre","Algunos programas cuentan la historia de Ciudad del Rey Don Felipe, establecimiento español del siglo XVI. Consulta si hay una parada efectiva."),
("Museo y centro de visitantes","La interpretación histórica se complementa con exposiciones y miradores, según la operación del parque. Verifica horarios, accesibilidad y ticket."),
("Media jornada o circuito extendido","Pregunta duración completa, recogida, inclusión de entradas, tiempo caminando y si combina otras paradas de la costa."),
("Consejos prácticos","Usa calzado cómodo y abrigo en capas. No prometas un almuerzo o recogida de cruceros hasta confirmar el programa.")],
'Yo buscaría una salida que dé tiempo al recorrido del parque, no solamente a la foto del fuerte.','ciudad',('estrecho','sernatur')),
('puerto-natales','Continuar hacia Puerto Natales','Punta Arenas puede ser el comienzo de un viaje por Magallanes, pero Puerto Natales merece su propia planificación.',[
('Conectar destinos','Chile Travel sitúa Puerto Natales a unos 250 km por la Ruta 9. Revisa el servicio y el tiempo real de tu transporte, sumando llegada, equipaje y traslados locales.'),('No confundir con Torres del Paine','Llegar a Natales no significa haber entrado al parque. Alojamiento, traslados, reservas y actividades de naturaleza requieren coordinación adicional. Evita una visita excesivamente apurada desde Punta Arenas.')],
'Yo separaría los destinos cuando tenga tiempo suficiente. Un viaje con pausas permite disfrutar más que una ruta hecha solo para marcar lugares.','ciudad',('natales',)),
]:add('tours',slug,title,intro,blocks,tip,image=img,sources=refs)

